  scale_ratio,
  weight_kg,
  length_m,
  height_m,
  lifespan_years,
  is_prehistoric,
  premium,
  accent,
  emoji,
  silhouette,
  popularity
)
values
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000001', 'african-bush-elephant', 'African Bush Elephant', 'Loxodonta africana', 'Mammal', 'African savanna, bush & woodland', 'Africa', 'Endangered', 'Herbivore', 'The largest living land animal, the African bush elephant moves across the savanna in matriarch-led herds that share knowledge of waterholes across generations. Its dexterous trunk fuses the nose and upper lip, and its huge ears act as radiators that dump heat into the shade.', array['An elephant''s trunk contains roughly 40,000 muscles, far more than a human body has.', 'The ears can be flapped to shed heat and are shaped a little like the African continent.', 'Elephants dig for water with their tusks and trunk, creating pools other species rely on.', 'A calf can stand within an hour of birth and is protected by the whole herd.']::text[], '/models/african-bush-elephant.glb', null, null, 3.2, 6000, 6.5, 3.2, '60-70 years', false, false, array['#9aa3a8', '#3a3a3c']::text[], '🐘', 'quadruped', 96),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000002', 'axolotl', 'Axolotl', 'Ambystoma mexicanum', 'Amphibian', 'Freshwater canals & lakes of Xochimilco, Mexico', 'North America', 'Critically Endangered', 'Carnivore', 'The axolotl is a salamander that never grows up: it keeps its feathery larval gills and stays aquatic for life. Once abundant in the canals of Xochimilco, wild numbers have collapsed as the waterways are drained, polluted and stocked with introduced fish.', array['It can regenerate whole limbs, its tail, and parts of its heart and brain without scarring.', 'Keeping juvenile features into adulthood is called neoteny, and the axolotl is its famous example.', 'Its name comes from Xolotl, the Aztec god associated with transformation and death.', 'Wild axolotls survive only in the Xochimilco canal system on the southern edge of Mexico City.']::text[], '/models/axolotl.glb', null, null, 0.25, 0.15, 0.25, 0.08, '10-15 years', false, false, array['#f2a0c0', '#2b1b2e']::text[], '🦎', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000003', 'bald-eagle', 'Bald Eagle', 'Haliaeetus leucocephalus', 'Bird', 'Lakeshores, rivers & coasts of North America', 'North America', 'Least Concern', 'Piscivore', 'A sea eagle of North American waterways, the bald eagle snatches fish from the surface with talons that lock shut on contact. Its white head and tail only appear at about five years old, which is why the national bird is also called the white-headed eagle.', array['Wingspan can reach 2.3 metres, yet the skeleton weighs less than the bird''s feathers.', 'Its stick nests are among the largest built by any bird and are reused and enlarged for years.', 'The name comes from an old sense of bald meaning white-headed, not hairless.', 'A hunting eagle can stoop through the air at close to 160 km/h.']::text[], '/models/bald-eagle.glb', null, '/sounds/bald-eagle.mp3', 0.9, 5, 0.9, 0.7, '20-30 years', false, false, array['#f5f1e6', '#3b2a1a']::text[], '🦅', 'bird', 94),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000005', 'blue-whale', 'Blue Whale', 'Balaenoptera musculus', 'Mammal', 'Open ocean, feeding in cold polar seas', 'Oceans', 'Endangered', 'Filter Feeder', 'The largest animal known to have lived, the blue whale sieves swarms of krill through baleen plates the size of fence slats. It feeds in cold, rich polar waters in summer and migrates thousands of kilometres toward the tropics to breed.', array['Its heart can weigh around 180 kg, about as much as a small car engine.', 'The tongue alone can weigh as much as an adult elephant.', 'A blue whale can eat up to four tonnes of krill in a single day.', 'Its low-frequency calls exceed 180 decibels and travel for hundreds of kilometres underwater.']::text[], '/models/blue-whale.glb', null, '/sounds/blue-whale.ogg', 27, 130000, 27, 4.5, '80-90 years', false, false, array['#3a6fb0', '#12233d']::text[], '🐋', 'whale', 97),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000008', 'giant-panda', 'Giant Panda', 'Ailuropoda melanoleuca', 'Mammal', 'Temperate bamboo forest of central China', 'Asia', 'Vulnerable', 'Herbivore', 'A bear that eats like a herbivore, the giant panda spends up to fourteen hours a day stripping bamboo, which its gut digests poorly. Its black-and-white coat and its enlarged wrist bone, which works as a thumb, suit a carnivore turned full-time browser.', array['A panda eats 12 to 38 kg of bamboo every day to stay fed.', 'An enlarged wrist bone works as a sixth thumb for gripping bamboo stems.', 'Newborn cubs weigh about 100 grams, roughly a thousandth of their mother''s weight.', 'Despite their bulk, pandas climb trees well and often nap in the branches.']::text[], '/models/giant-panda.glb', null, '/sounds/giant-panda.ogg', 1.6, 110, 1.6, 0.85, '20-30 years', false, false, array['#f2f2f0', '#1c1c1e']::text[], '🐼', 'quadruped', 95),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000009', 'giraffe', 'Giraffe', 'Giraffa camelopardalis', 'Mammal', 'African savanna & open woodland', 'Africa', 'Vulnerable', 'Herbivore', 'The world''s tallest animal browses acacia crowns that no other herbivore can reach, using a prehensile 45-centimetre tongue to strip thorny leaves. Its long neck carries the same seven vertebrae as a human''s, each one enormously elongated.', array['A giraffe''s heart can weigh about 11 kg and pumps blood two metres up to the head.', 'The tongue is dark purple, which may protect it from sunburn while feeding.', 'No two giraffes share the same coat pattern, and each is stable for life.', 'Giraffes sleep very little, often in short bouts standing up.']::text[], '/models/giraffe.glb', null, null, 5.5, 1200, 4, 5.5, '20-25 years', false, false, array['#e0b25c', '#5a3a17']::text[], '🦒', 'quadruped', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000011', 'gray-wolf', 'Gray Wolf', 'Canis lupus', 'Mammal', 'Boreal forest, tundra & mountain ranges', 'Europe', 'Least Concern', 'Carnivore', 'The ancestor of every domestic dog, the gray wolf lives in family packs built around a breeding pair and their offspring. A single pack can patrol hundreds of square kilometres, shaping the movements of deer, elk and reindeer across the landscape.', array['A wolf pack is essentially a family, usually two parents and their young of several years.', 'A howl carries up to 10 km in open country and helps packs stay in contact.', 'Wolves routinely travel 30 km in a day and can cover far more when dispersing.', 'By culling weak prey, wolves keep herds healthier and reduce overgrazing.']::text[], '/models/gray-wolf.glb', null, '/sounds/gray-wolf.ogg', 1.5, 40, 1.5, 0.8, '6-8 years', false, false, array['#8d949c', '#2b3138']::text[], '🐺', 'quadruped', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000012', 'great-white-shark', 'Great White Shark', 'Carcharodon carcharias', 'Fish', 'Temperate & subtropical coastal seas', 'Oceans', 'Vulnerable', 'Carnivore', 'The great white is a torpedo-shaped lamnid shark that hunts seals and large fish in cool coastal waters, sometimes launching its whole body clear of the surface. Pores on its snout detect the faint electrical fields of a hidden fish, and it keeps its muscles warmer than the surrounding sea.', array['Ampullae of Lorenzini on its snout sense electrical fields produced by living prey.', 'It is one of the few fish that is partially warm-blooded, holding heat in its swimming muscles.', 'Females grow larger than males and can exceed 5 metres in length.', 'Attacks on surfboards from below often follow a full breach, with the shark leaving the water entirely.']::text[], '/models/great-white-shark.glb', null, null, 5, 1100, 5, 1.2, '70 years', false, false, array['#8fa3ad', '#22303a']::text[], '🦈', 'marine', 96),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000014', 'king-cobra', 'King Cobra', 'Ophiophagus hannah', 'Reptile', 'South & Southeast Asian forest and plantation', 'Asia', 'Vulnerable', 'Carnivore', 'The longest venomous snake in the world, the king cobra specialises in eating other snakes, including cobras and pythons. Unusually for a snake, the female builds a nest of leaf litter and guards her eggs until they hatch.', array['It can exceed 5 metres in length, making it the longest venomous snake alive.', 'Its scientific name, Ophiophagus, means snake-eater.', 'It can rear up a third of its body and advance on an intruder while holding that pose.', 'The female stays with her nest for weeks, the closest thing to parental care among snakes.']::text[], '/models/king-cobra.glb', null, null, 4, 6, 4, 0.3, '20 years', false, false, array['#b9a24b', '#23301f']::text[], '🐍', 'serpent', 87),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000015', 'lion', 'Lion', 'Panthera leo', 'Mammal', 'African savanna & grassland', 'Africa', 'Vulnerable', 'Carnivore', 'Lions are the only cats that live in permanent social groups, and a pride''s females do most of the hunting as a coordinated team. A male''s mane darkens with age and condition, advertising his fitness to rivals and mates alike.', array['A lion''s roar carries about 8 km across open savanna at night.', 'Pride females usually hunt together, fanning out to ambush herds from different sides.', 'Male lions can sleep for up to 20 hours a day between patrols.', 'Cubs are born with faint spots that fade as they grow.']::text[], '/models/lion.glb', null, '/sounds/lion.ogg', 2.5, 190, 2.5, 1.2, '10-14 years', false, false, array['#e8a33d', '#3d2410']::text[], '🦁', 'quadruped', 99),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000016', 'megalodon', 'Megalodon', 'Otodus megalodon', 'Fish', 'Warm Miocene & Pliocene seas worldwide', 'Oceans', 'Extinct', 'Carnivore', 'Megalodon was a shark that grew longer than a city bus, hunting whales and other large marine mammals in warm seas for over thirteen million years. It is known mostly from its enormous fossil teeth, which are common enough to wash up on beaches today.', array['Its triangular teeth reached about 18 cm in slant height, among the largest of any fish.', 'Estimated bite forces exceed those calculated for Tyrannosaurus rex.', 'Nursery areas in shallow coastal water have been identified from fossil juvenile teeth.', 'It disappeared around 3.6 million years ago as oceans cooled and its prey shifted poleward.']::text[], '/models/megalodon.glb', null, null, 16, 50000, 16, 3.5, 'Unknown', true, true, array['#c8b48a', '#2b2118']::text[], '🦷', 'marine', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000017', 'monarch-butterfly', 'Monarch Butterfly', 'Danaus plexippus', 'Insect', 'Milkweed meadows & overwintering groves', 'North America', 'Endangered', 'Herbivore', 'Each autumn monarchs east of the Rockies stream up to 4,800 km to a handful of mountain forests in central Mexico, roosting in such dense clusters that branches bend under their weight. Caterpillars eat only milkweed, storing its toxins to make themselves poisonous to birds.', array['The orange wings warn predators of toxins absorbed from milkweed as a caterpillar.', 'No single butterfly makes the round trip: the return north takes three or four generations.', 'Overwintering colonies in Mexico can contain tens of millions of individuals.', 'A tagged monarch has been recorded flying nearly 4,800 km from Canada to Mexico.']::text[], '/models/monarch-butterfly.glb', null, null, 0.1, 0.0005, 0.1, 0.03, '2-6 weeks, 8-9 months for the migratory generation', false, false, array['#f08a1d', '#241a2e']::text[], '🦋', 'insect', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000019', 'saltwater-crocodile', 'Saltwater Crocodile', 'Crocodylus porosus', 'Reptile', 'Mangroves, estuaries & coastal rivers', 'Oceania', 'Least Concern', 'Carnivore', 'The largest living reptile patrols mangroves and estuaries from eastern India to northern Australia, ambushing prey at the water''s edge with a bite measured as the strongest of any living animal. It tolerates salt water well enough to cross open ocean between islands.', array['Large males can exceed 6 metres and weigh over 1,000 kg.', 'Its bite has been measured as the most powerful of any living animal.', 'It can launch its body almost completely out of the water to seize prey above the surface.', 'Salt glands on the tongue let it survive for weeks in full-strength seawater.']::text[], '/models/saltwater-crocodile.glb', null, null, 5, 500, 5, 0.6, '60-70 years', false, false, array['#6f7f4a', '#2a2f1e']::text[], '🐊', 'quadruped', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000020', 'smilodon', 'Smilodon', 'Smilodon fatalis', 'Mammal', 'Pleistocene grassland & woodland of the Americas', 'North America', 'Extinct', 'Carnivore', 'Smilodon, the saber-toothed cat, ambushed large Pleistocene herbivores with canine teeth nearly 30 cm long. Its stocky body and powerful forelimbs were built for wrestling prey to the ground rather than for long chases.', array['Its upper canines could reach about 28 cm, including the root.', 'Smilodon had unusually robust forelimbs, useful for pinning struggling prey.', 'Thousands of Smilodon fatalis fossils have been recovered from the La Brea Tar Pits in Los Angeles.', 'It died out roughly 10,000 years ago, along with much of the Pleistocene megafauna.']::text[], '/models/smilodon.glb', null, null, 1.2, 280, 2.1, 1.2, 'Unknown', true, true, array['#c9a06a', '#43301f']::text[], '🦴', 'quadruped', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000021', 'toco-toucan', 'Toco Toucan', 'Ramphastos toco', 'Bird', 'South American savanna, forest edge & palm groves', 'South America', 'Least Concern', 'Omnivore', 'The toco toucan carries the largest bill of any toucan, a hollow 20-centimetre structure that looks heavy but weighs less than its feathers. It plucks fruit at the end of thin branches and tosses each item into the air before catching and swallowing it.', array['Its bill is mostly air-filled keratin, so it is far lighter than it looks.', 'Blood vessels in the bill shed heat, making it an important radiator in the tropics.', 'It sleeps with the bill resting along its back and the tail folded over it.', 'Toucans nest in tree cavities and are important seed dispersers in the Cerrado and Amazon.']::text[], '/models/toco-toucan.glb', null, '/sounds/toco-toucan.ogg', 0.6, 0.7, 0.6, 0.35, '20 years', false, false, array['#f26b21', '#1b1b1f']::text[], '🦜', 'bird', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000022', 'tyrannosaurus-rex', 'Tyrannosaurus rex', 'Tyrannosaurus rex', 'Reptile', 'Late Cretaceous floodplains & forests', 'North America', 'Extinct', 'Carnivore', 'Tyrannosaurus rex was a 12-metre predator of the Late Cretaceous, with a skull built to deliver one of the most powerful bites of any land animal. Its arms were famously short, yet each was strong enough to hold struggling prey close.', array['Its bite force is estimated among the highest of any land animal that has ever lived.', 'Around 60 teeth lined its jaws, some over 30 cm long including the root.', 'Its arms were short but heavily muscled, with two clawed fingers on each hand.', 'It lived between about 68 and 66 million years ago, at the very end of the dinosaur era.']::text[], '/models/tyrannosaurus-rex.glb', null, null, 12.3, 8000, 12.3, 4, 'Unknown', true, true, array['#6b8f3e', '#2a2418']::text[], '🦖', 'theropod', 97),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000023', 'weddell-seal', 'Weddell Seal', 'Leptonychotes weddellii', 'Mammal', 'Fast ice & coastal waters around Antarctica', 'Antarctica', 'Least Concern', 'Piscivore', 'The Weddell seal lives further south than any other mammal, hauling out on the fast ice around Antarctica and slipping into the water through holes it keeps open with its teeth. It dives deeper and longer than almost any other seal, hunting fish beneath metres of ice.', array['It can dive deeper than 600 metres and stay submerged for over an hour.', 'Seals rasp their breathing holes open with their teeth, which wear down over a lifetime.', 'Weddell seals are the most southerly breeding mammal on Earth.', 'Pups are born on the ice in spring and can swim within days.']::text[], '/models/weddell-seal.glb', null, null, 3, 450, 3, 0.6, '20-25 years', false, false, array['#a8b6bd', '#33414d']::text[], '🦭', 'marine', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000024', 'woolly-mammoth', 'Woolly Mammoth', 'Mammuthus primigenius', 'Mammal', 'Ice Age mammoth steppe of Eurasia', 'Europe', 'Extinct', 'Herbivore', 'The woolly mammoth roamed the cold grasslands of Ice Age Eurasia, wrapped in a dense coat of guard hairs and wool with a layer of fat beneath. Curved tusks up to four metres long were used to sweep snow aside in search of frozen grass.', array['Its tusks could grow to about 4 metres and are among the largest of any elephant relative.', 'Small ears and a short tail limited heat loss in the freezing steppe climate.', 'Whole carcasses with skin and hair intact have been recovered from Siberian permafrost.', 'A dwarfed population survived on Wrangel Island until roughly 4,000 years ago.']::text[], '/models/woolly-mammoth.glb', null, null, 3.4, 6000, 5, 3.4, '60-80 years', true, true, array['#a9744f', '#4a3524']::text[], '🦣', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000025', 'polar-bear', 'Polar Bear', 'Ursus maritimus', 'Mammal', 'Arctic sea ice, coastlines & tundra', 'North America', 'Vulnerable', 'Carnivore', 'The polar bear is a sea-ice hunter that spends most of its life on frozen ocean, moving between floes to ambush ringed and bearded seals at their breathing holes. Its fur carries no white pigment, its skin underneath is black, and a thick layer of blubber lets it swim for hours in water close to freezing.', array['Its fur is transparent rather than white; the hairs scatter light, and the skin beneath is black.', 'A polar bear can swim for days at a time, paddling with its wide front paws.', 'Pregnant females dig dens in snowdrifts and fast for months while nursing their cubs.', 'It is classed as a marine mammal, and its main prey is seal rather than fish.']::text[], '/models/polar-bear.glb', null, null, 2.4, 450, 2.4, 1.4, '25-30 years', false, false, array['#eef1f2', '#3b4c58']::text[], '🐻‍❄️', 'quadruped', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000026', 'snow-leopard', 'Snow Leopard', 'Panthera uncia', 'Mammal', 'High mountains of Central Asia', 'Asia', 'Vulnerable', 'Carnivore', 'The snow leopard lives above the tree line in the mountains of Central Asia, stalking ibex and blue sheep across cliffs and scree. Its long tail works as a counterweight on steep ground, and its paws are furred underneath for grip on snow.', array['The tail can be almost as long as the body and is thick with fat and fur.', 'Snow leopards cannot roar; they chuff, mew and purr.', 'Each cat''s rosette pattern is unique, which is how camera traps tell individuals apart.', 'Its fur grows up to 12 cm long on the back in winter.']::text[], '/models/snow-leopard.glb', null, null, 1.1, 45, 1.1, 0.56, '15-18 years', false, false, array['#e8e4d9', '#5c6470']::text[], '🐆', 'quadruped', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000027', 'cheetah', 'Cheetah', 'Acinonyx jubatus', 'Mammal', 'African savanna & dry grassland', 'Africa', 'Vulnerable', 'Carnivore', 'The cheetah is the fastest land animal over short distances, reaching about 100 km/h in a sprint that lasts a few hundred metres. It has a slim, deep-chested build, claws that stay out like running studs, and a long tail that swings out to steer through a turn.', array['Every cheetah has its own spot pattern, and a black tear-stripe runs from each eye to the mouth.', 'It can accelerate from a standstill to highway speed in about three seconds.', 'A hunt usually ends inside 20 seconds, after which the cat must rest.', 'Brothers often form coalitions that hold a territory together for years.']::text[], '/models/cheetah.glb', null, null, 1.3, 50, 1.3, 0.8, '10-15 years', false, false, array['#e3b45c', '#2f2a24']::text[], '🐆', 'quadruped', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000029', 'spotted-hyena', 'Spotted Hyena', 'Crocuta crocuta', 'Mammal', 'African savanna, woodland & desert edge', 'Africa', 'Least Concern', 'Carnivore', 'The spotted hyena lives in clans of up to eighty animals in which females are larger and outrank the males. It hunts most of what it eats, and its jaws can crack the leg bones of a giraffe, so a clan can finish a carcass that lions have left.', array['The clan is led by females, who feed first at every kill.', 'Its whooping laugh carries for kilometres and signals age and social rank, not amusement.', 'Hyenas digest bone, hide and horn, and their droppings are white with calcium.', 'Cubs are born with their eyes open and with teeth already through.']::text[], '/models/spotted-hyena.glb', null, null, 1.3, 60, 1.3, 0.8, '12-20 years', false, false, array['#c9b28b', '#3a3227']::text[], '🐕', 'quadruped', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000030', 'wolverine', 'Wolverine', 'Gulo gulo', 'Mammal', 'Boreal forest, tundra & alpine scrub', 'North America', 'Least Concern', 'Carnivore', 'The wolverine is the largest land-dwelling mustelid, a stocky animal built for snow and long distances rather than speed. It patrols a vast home range alone, scavenging carcasses and killing prey in deep drifts, and its wide, furred paws spread its weight on top of the snow.', array['Males are about a third heavier than females and may hold ranges of several hundred square kilometres.', 'It can chew through frozen carrion that other predators abandon.', 'A strong-smelling secretion is used to mark food caches and territory.', 'It dens in deep snow, and cubs stay with the female for about a year.']::text[], '/models/wolverine.glb', null, null, 0.85, 15, 0.85, 0.4, '5-7 years', false, false, array['#6b5b4a', '#1f1c19']::text[], '🦡', 'quadruped', 74),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000033', 'chimpanzee', 'Chimpanzee', 'Pan troglodytes', 'Mammal', 'Equatorial African forest & savanna woodland', 'Africa', 'Endangered', 'Omnivore', 'Chimpanzees live in communities of up to 200 animals that split into small parties to forage by day. They eat fruit, leaves, insects and meat, and they are among the few animals that make and use tools, fishing termites out of mounds with stripped twigs. Males usually stay in their birth community while females move away.', array['Each community has its own set of tool-using and grooming traditions.', 'Chimpanzees hunt monkeys cooperatively and share the meat.', 'They build a fresh nest of leaves and branches in the trees every night.', 'A chimpanzee can recognise itself in a mirror.']::text[], '/models/chimpanzee.glb', null, null, 1.5, 40, 0.9, 1.5, '40-60 years', false, false, array['#3b3129', '#161310']::text[], '🐵', 'biped', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000034', 'hippopotamus', 'Hippopotamus', 'Hippopotamus amphibius', 'Mammal', 'Rivers, lakes & wetlands of sub-Saharan Africa', 'Africa', 'Vulnerable', 'Herbivore', 'The hippopotamus stands or floats in shallow water through the day and comes ashore at dusk to graze on grass, walking several kilometres from the river. Its skin secretes a reddish fluid often called blood sweat, which acts as a sunscreen and an antibiotic. Despite its bulk it can outrun a human on land.', array['A hippo can hold its breath for about five minutes and closes its ears and nostrils underwater.', 'Its closest living relatives are whales and dolphins, not pigs.', 'Males fight over stretches of water with lower canines that never stop growing.', 'Calves are born underwater and must surface to take their first breath.']::text[], '/models/hippopotamus.glb', null, null, 4, 1500, 4, 1.5, '45-55 years', false, false, array['#8a7f74', '#3a2f2a']::text[], '🦛', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000035', 'white-rhinoceros', 'White Rhinoceros', 'Ceratotherium simum', 'Mammal', 'African grassland & savanna', 'Africa', 'Near Threatened', 'Herbivore', 'The white rhinoceros is the largest living rhino and a pure grazer, cropping short grass with a wide, square lip. It carries two horns made of keratin, the same protein as hair and fingernails. The name has nothing to do with colour: it is usually traced to the Dutch word wijd, describing the width of its mouth.', array['The southern subspecies recovered from fewer than a hundred animals to more than fifteen thousand.', 'The northern white rhinoceros survives only as two females and frozen embryos.', 'A rhino horn is not bone, and it regrows if it is cut cleanly.', 'White rhinos are the most social rhinos and often graze in small groups.']::text[], '/models/white-rhinoceros.glb', null, null, 3.7, 2000, 3.7, 1.8, '40-50 years', false, false, array['#b8b2a6', '#40403c']::text[], '🦏', 'quadruped', 87),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000036', 'plains-zebra', 'Plains Zebra', 'Equus quagga', 'Mammal', 'East & southern African savanna grassland', 'Africa', 'Near Threatened', 'Herbivore', 'The plains zebra is the most widespread of the three zebra species, moving in herds that follow the rains across East and southern African grassland. Each animal''s stripe pattern is unique, and a foal learns its mother''s pattern within days of birth. Its teeth crop grass so short that wildebeest and gazelle can graze behind the herd.', array['The stripes may confuse biting flies, which land less often on patterned surfaces.', 'A zebra''s coat is black with white stripes, not white with black.', 'The quagga, a zebra striped only on the front half, was hunted to extinction by 1883.', 'Herd members take turns to sleep while others stand watch.']::text[], '/models/plains-zebra.glb', null, null, 2.3, 250, 2.3, 1.35, '20-25 years', false, false, array['#e8e6e1', '#2b2b2b']::text[], '🦓', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000037', 'american-bison', 'American Bison', 'Bison bison', 'Mammal', 'North American prairie & river valley', 'North America', 'Near Threatened', 'Herbivore', 'The American bison is the heaviest land animal in North America, a grazer of the prairies that once numbered in the tens of millions. Hunting reduced the herds to a few hundred animals in the nineteenth century, and every bison alive today descends from those survivors. Bulls carry a heavy shoulder hump and can push through deep snow to reach grass.', array['Bison wallow in shallow dust bowls to shed insects and rub off winter hair.', 'They can run at around 55 km/h despite weighing close to a tonne.', 'The species was reduced to as few as 541 animals before protection began.', 'The hump is muscle, anchored to long spines on the shoulder vertebrae.']::text[], '/models/american-bison.glb', null, null, 3, 730, 3, 1.75, '15-20 years', false, false, array['#6b4a31', '#241a12']::text[], '🦬', 'quadruped', 79),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000038', 'moose', 'Moose', 'Alces alces', 'Mammal', 'Northern boreal forest & wetland', 'North America', 'Least Concern', 'Herbivore', 'The moose is the largest deer, a browser of willow, birch and water plants that wades into lakes to feed. Bulls grow broad palmate antlers each spring and drop them in winter, and both sexes carry a flap of skin and hair under the chin called a bell. Long legs let it wade through deep snow and step over fallen timber.', array['An adult moose can eat around 30 kg of browse a day in summer.', 'Its antlers can span 1.8 metres and are regrown from scratch every year.', 'It can close its nostrils and browse underwater.', 'The shoulder hump stores fat and anchors the neck muscles.']::text[], '/models/moose.glb', null, null, 2.8, 500, 2.8, 1.9, '15-25 years', false, false, array['#4a3a2c', '#1a1512']::text[], '🫎', 'quadruped', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000040', 'giant-anteater', 'Giant Anteater', 'Myrmecophaga tridactyla', 'Mammal', 'Grassland, savanna & forest of Central & South America', 'South America', 'Vulnerable', 'Insectivore', 'The giant anteater walks on its knuckles to protect the long claws it uses to open termite mounds, and it feeds by flicking a sticky tongue up to 45 cm long into the tunnel around 150 times a minute. It has no teeth at all, crushing insects against the roof of its mouth instead. An animal may visit dozens of mounds in a day and rarely destroys one.', array['The tongue is anchored to the sternum and can only move in and out, not side to side.', 'A pup rides on its mother''s back for months, its coat matching hers.', 'It sleeps with its bushy tail wrapped over its body for warmth.', 'When cornered it rears up on its hind legs and slashes with its foreclaws.']::text[], '/models/giant-anteater.glb', null, null, 2, 40, 2, 0.6, '25 years (captivity)', false, false, array['#57514a', '#241f1a']::text[], '🐜', 'quadruped', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000044', 'arctic-fox', 'Arctic Fox', 'Vulpes lagopus', 'Mammal', 'Arctic tundra & sea ice', 'North America', 'Least Concern', 'Carnivore', 'The arctic fox lives on tundra and sea ice around the Arctic, hunting lemmings and scavenging the remains of polar bear kills. Its winter coat is white in most populations and blue-grey in coastal ones, and its rounded ears and short muzzle keep heat loss to a minimum.', array['It does not begin to shiver until roughly -70 °C, the best insulation recorded in a mammal.', 'It caches food in the ground during autumn for the lean winter months.', 'The blue morph is common near the coast, where snow cover is less reliable.', 'Arctic foxes trail polar bears to take scraps from their kills.']::text[], '/models/arctic-fox.glb', null, null, 0.55, 3.5, 0.55, 0.28, 'Up to 11 years', false, false, array['#f2f4f6', '#4a5a6a']::text[], '🦊', 'quadruped', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000045', 'humpback-whale', 'Humpback Whale', 'Megaptera novaeangliae', 'Mammal', 'Open ocean; feeds in cold polar seas and breeds in warm coastal waters', 'Oceans', 'Least Concern', 'Filter Feeder', 'The humpback is a baleen whale built for long migrations, feeding on krill and schooling fish in cold water each summer and travelling thousands of kilometres to warm, shallow breeding grounds in winter. Its pectoral fins are the longest of any whale, about a third of its body length, and it herds prey with spirals of exhaled bubbles. Adults run 14 to 15 metres, and females grow slightly longer than males.', array['Its genus name Megaptera means "great wing", after pectoral fins that can be five metres long.', 'Males sing long, structured songs that change over the years and spread from population to population.', 'A humpback''s tail flukes can be 5.5 metres wide and are serrated along the trailing edge.', 'It may live for over 50 years, and the oldest known individual was 95.']::text[], '/models/humpback-whale.glb', null, null, 16, 30000, 16, 3.5, '50-95 years', false, false, array['#5d7f9e', '#16283a']::text[], '🐋', 'whale', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000046', 'sperm-whale', 'Sperm Whale', 'Physeter macrocephalus', 'Mammal', 'Deep ocean; hunts squid far below the surface in all seas', 'Oceans', 'Vulnerable', 'Carnivore', 'The sperm whale is the largest toothed predator, its block-shaped head making up as much as a third of its length and carrying the biggest brain of any animal alive. It hunts squid in near-total darkness, diving to about 2,250 metres and surfacing to breathe for roughly eight minutes between plunges. Females and calves travel together in warm water while adult males range toward the poles.', array['Mature males average 16 metres and about 45 tonnes; females average 11 metres and 15 tonnes.', 'At 2,250 metres it is the third deepest-diving mammal, after the southern elephant seal and Cuvier''s beaked whale.', 'Sperm whales can live 70 years or more and often carry scars from the squid they fight.', 'Ambergris, a waxy material from the digestive tract, is still collected as a perfume fixative.']::text[], '/models/sperm-whale.glb', null, null, 16, 45000, 16, 4, '70 years or more', false, false, array['#7a7d84', '#1b1e23']::text[], '🐳', 'whale', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000047', 'orca', 'Orca', 'Orcinus orca', 'Mammal', 'All oceans, from polar pack ice to tropical seas', 'Oceans', 'Data Deficient', 'Carnivore', 'The orca, or killer whale, is the largest member of the dolphin family, marked by a tall dorsal fin and a black-and-white pattern that differs between populations. Pods hunt cooperatively, and their diets vary sharply: some groups take fish such as salmon, others hunt seals, dolphins and even large whales. Females live far longer than males and stop breeding decades before they die.', array['Males typically measure 6 to 8 metres and weigh over 6 tonnes; females run 5 to 7 metres and 3 to 4 tonnes.', 'Wild females average 50 to 80 years, while males average around 30.', 'Fish-eating and mammal-hunting groups differ in diet, calls and social structure, and rarely mix.', 'Orcas are one of the few animals that go through menopause and live on for decades afterwards.']::text[], '/models/orca.glb', null, null, 7.5, 6000, 7.5, 2, '30-80 years', false, false, array['#414b57', '#0e1218']::text[], '🐋', 'whale', 94),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000048', 'bottlenose-dolphin', 'Bottlenose Dolphin', 'Tursiops truncatus', 'Mammal', 'Coastal and offshore waters of warm and temperate seas', 'Oceans', 'Least Concern', 'Piscivore', 'The common bottlenose dolphin is the dolphin most people picture: grey, robust, and equally at home in estuaries, harbours and open ocean. It finds fish and squid by echolocation, often in coordinated groups, and each individual carries a signature whistle that others use like a name. Adults are usually 2.5 to 3.5 metres long and weigh 200 to 500 kilograms.', array['Dolphins can recognise the signature whistles of former companions after more than 20 years apart.', 'They eat 10 to 20 percent of their body weight each day, more when nursing a calf.', 'The average lifespan is at least 40 years and can reach 60, with females usually outliving males.', 'Inshore and offshore populations differ in size, diet and how far they travel.']::text[], '/models/bottlenose-dolphin.glb', null, null, 3, 300, 3, 0.8, '40-60 years', false, false, array['#7fa6c4', '#1d3648']::text[], '🐬', 'whale', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000049', 'narwhal', 'Narwhal', 'Monodon monoceros', 'Mammal', 'High Arctic fjords and pack ice of Canada, Greenland and Russia', 'Oceans', 'Least Concern', 'Carnivore', 'The narwhal is an Arctic whale with a mottled grey hide and, in males, a spiralled tusk that is really an overgrown left canine and can reach three metres. It winters among dense pack ice, breathing through leads and diving to depths of 2,370 metres for Greenland halibut, squid and shrimp. Its closest living relative is the beluga, with which it occasionally hybridises.', array['Adults measure 3.0 to 5.5 metres and weigh 800 to 1,600 kilograms.', 'The tusk is packed with millions of nerve endings and appears to sense temperature and salinity.', 'Age estimates from the eye lens suggest some females live past 100 years.', 'Most narwhals return to the same ice-free summering grounds year after year.']::text[], '/models/narwhal.glb', null, null, 4.5, 1200, 4.5, 1.2, '50-115 years', false, false, array['#a7b8c6', '#2b3a46']::text[], '🐋', 'whale', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000051', 'leopard-seal', 'Leopard Seal', 'Hydrurga leptonyx', 'Mammal', 'Antarctic pack ice and subantarctic islands', 'Antarctica', 'Least Concern', 'Carnivore', 'The leopard seal is the only large seal that regularly takes warm-blooded prey, hunting penguins and other seals as well as krill and fish. Females grow up to half again as large as males, and adults run 2.4 to 3.5 metres, with a long body, a reptilian-looking head and a wide gape. They keep to the pack ice for most of the year and wander north to subantarctic islands in winter.', array['Females can be up to 50 percent larger than males, an unusual gap for a carnivore.', 'Despite its reputation, krill and fish make up a large part of its diet by volume.', 'Wild leopard seals can live up to 26 years.', 'Males produce loud calls of 153 to 177 decibels and call for hours at a time.']::text[], '/models/leopard-seal.glb', null, null, 3, 400, 3, 0.8, 'up to 26 years', false, false, array['#9099a3', '#232a31']::text[], '🦭', 'marine', 70),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000053', 'california-sea-lion', 'California Sea Lion', 'Zalophus californianus', 'Mammal', 'Pacific coastlines, islands and docks from Canada to Mexico', 'North America', 'Least Concern', 'Piscivore', 'The California sea lion is the trained seal of aquaria and the loudest animal on many a harbour dock, an eared seal that swims with large foreflippers and walks on land on all fours. Males are much heavier than females and hold breeding territories on island rookeries through the summer. The population is large and still growing, and the species is listed as Least Concern.', array['Adult males reach 2.5 to 2.7 metres and about 350 kilograms; females are around 2.1 metres and 100 kilograms.', 'NOAA Fisheries gives their lifespan as 20 to 30 years, and one captive male reached 31.', 'Eared seals like this one have visible ear flaps and steer with the hind flippers, unlike true seals.', 'Bulls fast for weeks at a time while holding a territory on the rookery.']::text[], '/models/california-sea-lion.glb', null, null, 2.5, 300, 2.5, 0.9, '20-30 years', false, false, array['#a9855c', '#33261a']::text[], '🦭', 'marine', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000056', 'capybara', 'Capybara', 'Hydrochoerus hydrochaeris', 'Mammal', 'Amazonian wetlands, flooded savanna and riverbanks', 'South America', 'Least Concern', 'Herbivore', 'The capybara is the largest living rodent, a barrel-shaped grazer of rivers, marshes and flooded grassland across South America. It eats grasses and aquatic plants, has partly webbed feet, and escapes predators by diving, with eyes, ears and nostrils set high on the skull. Groups are dominated by one male and can hold twenty animals or more.', array['Adults grow to 106 to 134 centimetres in length, stand 50 to 62 centimetres at the shoulder and weigh 35 to 66 kilograms.', 'Capybaras eat their own droppings to recover gut bacteria that help them break down grass.', 'The maximum lifespan is 8 to 10 years, and captive animals may reach 12.', 'They are strong swimmers that can stay submerged for minutes at a time.']::text[], '/models/capybara.glb', null, null, 1.2, 50, 1.2, 0.6, '8-12 years', false, false, array['#9c7b52', '#33261a']::text[], '🦫', 'quadruped', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000058', 'jaguar', 'Jaguar', 'Panthera onca', 'Mammal', 'Amazonia, Pantanal wetlands and Central American forest', 'South America', 'Near Threatened', 'Carnivore', 'The jaguar is the largest cat of the Americas and the only Panthera species there, a stocky, short-tailed hunter whose rosettes enclose smaller spots. It kills large prey with a bite straight through the skull between the ears, and it swims well enough to take caiman and turtles in rivers and flooded forest. The biggest males reach 158 kilograms, and the species is listed as Near Threatened.', array['Body length runs 1.12 to 1.85 metres from nose to the base of the tail, and most adults weigh 56 to 96 kilograms.', 'It stands 57 to 81 centimetres at the shoulder.', 'Jaguars rarely live beyond 11 years in the wild, though captive animals may reach 22.', 'Unlike most cats, jaguars hunt in and around water and regularly take caiman and turtles.']::text[], '/models/jaguar.glb', null, null, 1.7, 80, 1.7, 0.7, '11-22 years', false, false, array['#d3a04a', '#1c1712']::text[], '🐆', 'quadruped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000059', 'ocelot', 'Ocelot', 'Leopardus pardalis', 'Mammal', 'Neotropical forest, thorn scrub and mangrove from Texas to Argentina', 'South America', 'Least Concern', 'Carnivore', 'The ocelot is the largest of the spotted Leopardus cats, patterned with chains of dark blotches that run into stripes along the neck and shoulders. It hunts at night and mostly alone, taking rodents, opossums, reptiles and birds along trails it reuses again and again. Adults stand about 45 centimetres at the shoulder and weigh 7 to 15.5 kilograms.', array['Head and body measure 55 to 100 centimetres, with a further 30 to 45 centimetres of tail.', 'Ocelots live about 7 to 10 years in the wild, and captive animals have reached 21.', 'The spotted coat was once so valuable that tens of thousands of skins were traded every year.', 'They sleep in dense thickets by day and are rarely seen even where they are common.']::text[], '/models/ocelot.glb', null, null, 0.8, 12, 0.8, 0.45, '7-20 years', false, false, array['#c78d43', '#221a10']::text[], '🐆', 'quadruped', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000060', 'serval', 'Serval', 'Leptailurus serval', 'Mammal', 'African grassland, wetland and highland moor', 'Africa', 'Least Concern', 'Carnivore', 'The serval is a slender African cat with very long legs, a small head and the largest ears, relative to body size, of any cat. It hunts by listening, then leaps over two metres into the air to land on rodents in tall grass with both forefeet. Up to 90 percent of what it catches weighs less than 200 grams, though it also takes birds, frogs, hares and young antelope.', array['It stands 54 to 62 centimetres at the shoulder, has a head-and-body length of 67 to 100 centimetres and weighs 8 to 18 kilograms.', 'Servals leap over 2 metres above the ground to pounce and can catch birds in flight.', 'Life expectancy is about 10 years in the wild and up to 20 in captivity.', 'A serval''s hearing is sharp enough to locate rodents moving underground.']::text[], '/models/serval.glb', null, null, 0.85, 12, 0.85, 0.58, '10-20 years', false, false, array['#d6b471', '#1f1a12']::text[], '🐆', 'quadruped', 64),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000062', 'fennec-fox', 'Fennec Fox', 'Vulpes zerda', 'Mammal', 'Sahara desert and North African sandy steppe', 'Africa', 'Least Concern', 'Omnivore', 'The fennec fox is the smallest canid, a nocturnal desert specialist whose ears can be ten centimetres long and which gives off heat as well as picking up the sound of prey under sand. It lives in family groups in burrows dug into dunes and stable sand, emerging at night to hunt insects and small vertebrates and to dig for roots. Its kidneys are efficient enough that it can go without drinking free water.', array['Females weigh 1 to 1.9 kilograms with a head-to-body length of 34.5 to 39.5 centimetres; males are slightly larger.', 'The average lifespan in the wild is about 10 years, and up to 14 in captivity.', 'Fennec foxes are strictly nocturnal, active in the cool hours of the desert night.', 'Pups are taken by eagle-owls and other desert predators, so litters are raised in deep burrows.']::text[], '/models/fennec-fox.glb', null, null, 0.4, 1.5, 0.4, 0.2, '10-14 years', false, false, array['#e0c9a4', '#3a2c1e']::text[], '🦊', 'quadruped', 81),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000068', 'snowy-owl', 'Snowy Owl', 'Bubo scandiacus', 'Bird', 'Arctic tundra of the circumpolar north', 'North America', 'Vulnerable', 'Carnivore', 'The snowy owl is the only owl with mainly white plumage, a day-and-night hunter of the open Arctic tundra that lives largely on lemmings. Mature males are almost pure white, while females and young birds keep dark barring across the body and wings. In winters after a good lemming season, many young owls move far south of the breeding range, sometimes reaching the northern United States.', array['It is the largest avian predator of the High Arctic and one of the largest owls in the world.', 'Females are heavier than males, averaging about 2.1 kg against roughly 1.66 kg.', 'It nests on open ground, often on a raised hummock with a wide view of the surrounding tundra.', 'The longest known wild lifespan is 23 years and 10 months, from a bird banded in Massachusetts and recovered in Montana.']::text[], '/models/snowy-owl.glb', null, null, 0.6, 2, 0.6, 0, '10-25 years', false, false, array['#f0f1f2', '#5a6470']::text[], '🦉', 'bird', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000071', 'california-condor', 'California Condor', 'Gymnogyps californianus', 'Bird', 'Mountain ranges & scrubland of the American Southwest', 'North America', 'Critically Endangered', 'Carnivore', 'The California condor is the largest bird in North America, a carrion feeder with the widest wingspan on the continent. By 1982 only 22 birds survived, all of them in captivity, and a breeding programme began returning them to the wild in 1991. Lead poisoning from spent ammunition remains the main threat, so released birds are monitored and recaptured for testing and treatment.', array['Its wingspan can reach about 2.8 metres, the largest of any North American bird.', 'The whole population fell to 22 individuals in 1982 before captive breeding pulled it back.', 'It can glide for hours on rising air and has been recorded flying as high as 4,600 metres.', 'A pair lays a single egg, usually every second year, and chicks depend on their parents for many months.']::text[], '/models/california-condor.glb', null, null, 1.3, 8.45, 1.3, 0, '45-60 years', false, false, array['#3a3633', '#c0703c']::text[], '🦅', 'bird', 70),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000072', 'peregrine-falcon', 'Peregrine Falcon', 'Falco peregrinus', 'Bird', 'Cliffs, coastlines & city towers worldwide', 'North America', 'Least Concern', 'Carnivore', 'The peregrine falcon is a bird-hunting raptor that stoops on its prey from above, folding its wings back and dropping at speeds recorded close to 390 km/h. Small bony tubercles in its nostrils are thought to steer the airflow of those dives away from the airway. It nests on cliffs and, since the 1990s, increasingly on towers and bridges in cities, where pigeons and starlings are easy prey.', array['A 2005 measurement of a stooping falcon recorded roughly 389 km/h, the fastest speed known for any animal.', 'Females are much larger than males, weighing 800 to 1,100 g against 500 to 700 g.', 'Pesticide use, especially DDT, crashed populations in the mid-twentieth century; they recovered after the ban.', 'Nesting pairs defend the site fiercely and have killed eagles that came too close.']::text[], '/models/peregrine-falcon.glb', null, null, 0.46, 0.8, 0.46, 0, '13-20 years', false, false, array['#8b98a5', '#2b3037']::text[], '🦅', 'bird', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000074', 'harpy-eagle', 'Harpy Eagle', 'Harpia harpyja', 'Bird', 'Lowland rainforest canopy of Central & South America', 'South America', 'Vulnerable', 'Carnivore', 'The harpy eagle is the heaviest eagle of the Neotropics, hunting monkeys, sloths and large birds in the canopy of lowland rainforest. Rather than soaring, it moves in short bursts between perches, using broad wings to manoeuvre between branches. Pairs raise a single chick every two or three years in a nest high in a kapok or similar emergent tree.', array['It has the largest talons of any living eagle, with claws up to about 12.5 cm long.', 'It is the national bird of Panama and appears on the country''s coat of arms.', 'It can carry prey weighing roughly half its own body weight.', 'Birds do not breed until they are four to six years old.']::text[], '/models/harpy-eagle.glb', null, null, 0.97, 7, 0.97, 0, '25-35 years', false, false, array['#8d9196', '#2c2f33']::text[], '🦅', 'bird', 71),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000075', 'scarlet-macaw', 'Scarlet Macaw', 'Ara macao', 'Bird', 'Humid lowland rainforest of Central & South America', 'South America', 'Least Concern', 'Herbivore', 'The scarlet macaw is a large, long-tailed parrot of Central and South American rainforest, usually seen flying in pairs or family parties above the canopy. More than half its length is tail, and it feeds on fruit, seeds and nuts, topping up its diet at riverbank clay licks. Pairs bond for life and nest in tree cavities, where they raise one or two chicks.', array['It gathers at clay licks to eat mineral-rich soil, which appears to supply sodium and calcium and to settle the stomach.', 'Most of its 84 cm length is the pointed, graduated tail.', 'Scarlet macaws are among the earliest parrots known to have bred in captivity.', 'A typical lifespan is 40 to 50 years, and captive birds have reached 75.']::text[], '/models/scarlet-macaw.glb', null, null, 0.86, 1, 0.86, 0, '40-50 years', false, false, array['#c9402f', '#2f5c9e']::text[], '🦜', 'bird', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000079', 'greater-flamingo', 'Greater Flamingo', 'Phoenicopterus roseus', 'Bird', 'Saline lagoons & shallow alkaline lakes', 'Africa', 'Least Concern', 'Filter Feeder', 'The greater flamingo is the largest and most widespread flamingo, feeding in saline lagoons and soda lakes from southern Europe and Africa to India. It stirs the mud with its feet, then pumps water through a filter-feeding bill held upside down to strain out brine shrimp, algae, seeds and larvae. Its pink colour comes from carotenoid pigments in that food, and colonies can number thousands of pairs on mounds of mud built in the shallows.', array['The pink colour comes from carotenoid pigments in the algae and crustaceans it eats.', 'It feeds with its head upside down, filtering water and mud through comb-like plates in the bill.', 'Most birds do not gain full adult plumage until about four years old.', 'The average wild lifespan is 30 to 40 years, and one bird at Adelaide Zoo lived to at least 83.']::text[], '/models/greater-flamingo.glb', null, null, 1.3, 3, 1.2, 1.3, '30-40 years', false, false, array['#e0aea8', '#3b4046']::text[], '🦩', 'bird', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000082', 'common-ostrich', 'Common Ostrich', 'Struthio camelus', 'Bird', 'African savanna & semi-desert', 'Africa', 'Least Concern', 'Omnivore', 'The common ostrich is the tallest and heaviest living bird, a flightless runner of African savanna that sustains about 55 km/h and bursts to roughly 70 km/h on its two toes. Its long neck and legs hold the head as much as 2.8 metres above the ground, and its eyes, about 50 mm across, are the largest of any land vertebrate. Males defend territories and several hens lay in one communal nest scraped into the ground.', array['It is the fastest land speed of any bipedal animal, with short bursts of up to about 70 km/h.', 'Its eyes are the largest of any land vertebrate, around 50 mm in diameter.', 'It lays the largest eggs of any living bird, roughly 15 cm long and 1.4 kg in weight.', 'A kick from its two-toed leg can injure or kill a lion.']::text[], '/models/common-ostrich.glb', null, null, 2.4, 110, 2, 2.4, '50-62 years', false, false, array['#6f6559', '#22201c']::text[], '🦃', 'bird', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000084', 'hoatzin', 'Hoatzin', 'Opisthocomus hoazin', 'Bird', 'Riverine forest & oxbow lakes of the Amazon and Orinoco basins', 'South America', 'Least Concern', 'Herbivore', 'The hoatzin is a pheasant-sized leaf-eater of Amazon and Orinoco river margins that digests foliage with bacteria in an enlarged crop, much as a cow does in its rumen. Young hoatzins hatch with two claws on each wing, which they use to clamber through branches and to climb back after dropping into water to escape danger. The fermenting gut gives the bird a manure-like smell, which is why local people call it the stinkbird.', array['It is the only bird known to break down plant matter by foregut fermentation, aided by specialised gut bacteria.', 'Chicks have two functional claws on each wing and lose them as they mature.', 'Because of its smell and its leafy diet, it is hunted for food only in times of need.', 'It is the national bird of Guyana, where it is known as the Canje pheasant.']::text[], '/models/hoatzin.glb', null, null, 0.65, 0.7, 0.65, 0, 'Unknown', false, false, array['#8b5a33', '#4a6f86']::text[], '🐦', 'bird', 55),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000085', 'komodo-dragon', 'Komodo Dragon', 'Varanus komodoensis', 'Reptile', 'Dry savanna, grassland & monsoon forest of the Lesser Sunda Islands', 'Asia', 'Endangered', 'Carnivore', 'The Komodo dragon is the largest living lizard, a monitor that grows longer than a tall man and hunts deer and wild pigs on a handful of Indonesian islands. It ambushes prey from cover and tears off chunks of meat too large to swallow, bracing the carcass with its forelegs. In 2009 researchers found venom glands in its lower jaw, replacing the older idea that its bite worked through septic bacteria alone.', array['Adult males average about 2.6 m from snout to tail tip and usually weigh around 70 kg.', 'A 2009 study described venom glands in the lower jaw, a finding that displaced the older bacteria hypothesis.', 'Females can lay fertile eggs without mating, a form of reproduction called parthenogenesis.', 'With a favourable wind a dragon can detect carrion up to 9.5 km away.']::text[], '/models/komodo-dragon.glb', null, null, 2.6, 70, 2.6, 0, '30-50 years', false, false, array['#8a7a52', '#2f2b22']::text[], '🦎', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000087', 'green-sea-turtle', 'Green Sea Turtle', 'Chelonia mydas', 'Reptile', 'Seagrass meadows, lagoons & nesting beaches of tropical seas', 'Oceans', 'Least Concern', 'Herbivore', 'The green sea turtle grazes seagrass and algae in shallow tropical water, and it takes its name from the green fat laid down under its shell by that diet rather than from the colour of the carapace. Adults migrate hundreds of kilometres between feeding grounds and the beaches where they hatched, where females haul out to dig nests in the sand. The IUCN moved the global population to Least Concern in October 2025, though several regional populations remain at risk.', array['Adults grow to about 1.5 m and mature individuals usually weigh between 150 and 200 kg.', 'The temperature of the nest, not genetics, decides whether the hatchlings are male or female.', 'Females return to lay on the same beach where they themselves hatched.', 'The largest known individual weighed 395 kg and measured 153 cm in carapace length.']::text[], '/models/green-sea-turtle.glb', null, null, 1.5, 175, 1.5, 0, '75 years', false, false, array['#5f7f5a', '#1f3324']::text[], '🐢', 'marine', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000089', 'american-alligator', 'American Alligator', 'Alligator mississippiensis', 'Reptile', 'Freshwater marshes, swamps & rivers of the southeastern United States', 'North America', 'Least Concern', 'Carnivore', 'The American alligator is the largest crocodilian of the southeastern United States, at home in marshes, cypress swamps and slow rivers from Texas to North Carolina. It digs and maintains pools known as gator holes that hold water through dry spells and are used by fish, turtles and wading birds. Hunting brought the species close to extinction before protection allowed it to recover across most of its range.', array['Its bite has been measured at more than 13,000 newtons, the strongest recorded in a living animal in the laboratory.', 'Females build mounds of vegetation as nests and stay close while the eggs incubate.', 'Nest temperature decides the sex of the hatchlings.', 'It survives cold snaps by keeping its nostrils above the surface of freezing water.']::text[], '/models/american-alligator.glb', null, null, 3.5, 150, 3.5, 0, '50-70 years', false, false, array['#4f5a3c', '#20241a']::text[], '🐊', 'quadruped', 87),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000090', 'gila-monster', 'Gila Monster', 'Heloderma suspectum', 'Reptile', 'Sonoran & Mojave desert scrub and rocky foothills', 'North America', 'Near Threatened', 'Carnivore', 'The Gila monster is a heavy, slow-moving venomous lizard of the deserts of Arizona, New Mexico and northern Mexico, and the only venomous lizard native to the United States. It spends most of the year in burrows and comes out to take eggs and nestling birds and mammals, chewing its food rather than swallowing it whole. A peptide isolated from its venom became the basis for a class of drugs used to treat type 2 diabetes.', array['It produces venom in glands in the lower jaw, not in glands behind the eyes as snakes do.', 'One component of the venom, exendin-4, led to the GLP-1 drugs used for type 2 diabetes.', 'Adults typically weigh 550 to 800 g and are heavy enough to be slow and deliberate.', 'An adult can take up to 35% of its own body weight in a single feeding and digest it over days.']::text[], '/models/gila-monster.glb', null, null, 0.5, 0.7, 0.5, 0, '8-20 years', false, false, array['#8c6a4a', '#241d16']::text[], '🦎', 'quadruped', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000091', 'black-mamba', 'Black Mamba', 'Dendroaspis polylepis', 'Reptile', 'Savanna, woodland & rocky slopes of sub-Saharan Africa', 'Africa', 'Least Concern', 'Carnivore', 'The black mamba is the longest venomous snake in Africa and the second longest in the world, hunting birds and small mammals by day across savanna, woodland and rocky ground. Its name refers to the inside of its mouth, which it opens wide when threatened, not to its skin, which is grey, olive or brown. The venom is a fast-acting neurotoxin, and a bite is a medical emergency.', array['Adults typically measure 2 to 3 m, with mature snakes commonly reaching 2.5 m.', 'Over suitable ground it can travel at up to 16 km/h for short distances.', 'It lays 6 to 17 eggs, and hatchlings are already 40 to 60 cm long.', 'Reported speeds above 20 km/h are exaggerated; it cannot outrun a person over any distance.']::text[], '/models/black-mamba.glb', null, null, 2.5, 1.6, 2.5, 0, '11 years', false, false, array['#5a5f4a', '#1c1f18']::text[], '🐍', 'serpent', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000094', 'poison-dart-frog', 'Poison Dart Frog', 'Dendrobatidae', 'Amphibian', 'Rainforest floor, leaf litter & bromeliads of Central and South America', 'South America', 'Data Deficient', 'Insectivore', 'Poison dart frogs are a family of small, day-active frogs from the wet forests of Central and South America, most of them brightly coloured. Their skin alkaloids are not made by the frogs themselves but taken from the ants, mites and termites they eat, which is why captive-bred animals lose their toxicity. Only four of the more than 170 species have been documented as sources of blowdart poison.', array['Most species are smaller than 2 cm as adults, though a few reach 6 cm.', 'Adults carry tadpoles on their backs, one at a time, to pools or to water held in bromeliads.', 'Frogs raised on captive diets do not develop the toxins of wild animals.', 'Their bright colours are a warning signal, a pattern known as aposematism.']::text[], '/models/poison-dart-frog.glb', null, null, 0.03, 0.003, 0.03, 0, 'Up to 25 years', false, false, array['#2f6fd0', '#12172b']::text[], '🐸', 'quadruped', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000098', 'whale-shark', 'Whale Shark', 'Rhincodon typus', 'Fish', 'Warm surface waters of tropical and warm temperate seas', 'Oceans', 'Endangered', 'Filter Feeder', 'The whale shark is the largest fish alive, a filter-feeding carpet shark that cruises warm surface water with its mouth open, straining plankton and small fish through sieve-like pads in its gills. Its skin carries a pattern of pale spots unique to each animal, and researchers photograph them to track individuals across oceans. Despite its size it is harmless to people and feeds on some of the smallest prey in the sea.', array['A reliably measured individual reached 18.8 m, and animals around 12 m are regularly seen.', 'It can process more than 6,000 litres of water an hour through its gill pads.', 'The spot pattern on its skin is unique and is used like a fingerprint to identify individuals.', 'Its skin can be up to 15 cm thick.']::text[], '/models/whale-shark.glb', null, null, 12, 12000, 12, 0, '80-130 years', false, false, array['#4a6a7a', '#16232b']::text[], '🦈', 'whale', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000099', 'giant-manta-ray', 'Giant Manta Ray', 'Mobula birostris', 'Fish', 'Tropical & temperate open ocean and coastal reefs', 'Oceans', 'Endangered', 'Filter Feeder', 'The giant manta ray is the largest ray in the world, a filter feeder that flies through the water on triangular pectoral fins and funnels plankton into its mouth as it swims. It carries the largest brain of any fish and visits cleaning stations where small reef fish pick parasites from its skin. Populations have fallen sharply over the past two decades, largely through fishing for its gill plates.', array['The typical disc width is about 4.5 m, and the largest animals reach 7 m across and about 3,000 kg.', 'Its brain can weigh up to 200 g, five to ten times more than that of a whale shark.', 'Pups are born at about 1.4 m across and already resemble small adults.', 'Each manta carries a pattern of spots on its underside that is unique to it.']::text[], '/models/giant-manta-ray.glb', null, null, 4.5, 3000, 4.5, 0, '20 years', false, false, array['#3a5a6a', '#111d24']::text[], '🐟', 'marine', 81),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000104', 'electric-eel', 'Electric Eel', 'Electrophorus electricus', 'Fish', 'Murky creeks, floodplains & oxbow lakes of the Guiana Shield', 'South America', 'Least Concern', 'Carnivore', 'The electric eel is a knifefish of the Amazon and Orinoco floodplains that generates electricity from three modified muscle organs and uses it to stun prey and to sense its surroundings. It is an obligate air-breather that surfaces every few minutes, and it hunts fish in water too murky to see through. It is not related to true eels, and in 2019 the genus was split into three species.', array['It can reach 2 m and 20 kg, and captive animals have lived for more than 20 years.', 'Species of the genus can discharge up to 860 volts, the strongest shock known in any animal.', 'It must surface to breathe air and would drown without access to the surface.', 'Its spine keeps adding vertebrae for as long as it lives.']::text[], '/models/electric-eel.glb', null, null, 2, 20, 2, 0, '20+ years', false, false, array['#4a4a30', '#15170f']::text[], '🐟', 'serpent', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000096', 'hellbender', 'Hellbender', 'Cryptobranchus alleganiensis', 'Amphibian', 'Clear, fast-flowing rivers & streams of the eastern United States', 'North America', 'Vulnerable', 'Carnivore', 'The hellbender is the largest salamander in North America, a flattened, olive-brown animal that hides under slab rocks in clean, fast rivers and rarely leaves the water. It breathes mainly through folds of skin along its sides and hunts crayfish and small fish at night. Sediment, pollution and impoundments have removed it from much of its former range, and it is now classed as Vulnerable.', array['Adults weigh 1.5 to 2.5 kg and can reach 74 cm in total length.', 'Its lateral skin folds work as gills, and it makes little use of its lungs.', 'Juveniles lose their external gills at about 18 months, when they are roughly 13 cm long.', 'Adults can live 25 to 30 years and take about five years to reach sexual maturity.']::text[], '/models/hellbender.glb', null, null, 0.6, 2, 0.6, 0, '25-30 years', false, false, array['#6b6a4a', '#22241a']::text[], '🦎', 'quadruped', 62),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000105', 'emperor-scorpion', 'Emperor Scorpion', 'Pandinus imperator', 'Arachnid', 'Rainforest floor & savanna burrows of West Africa', 'Africa', 'Data Deficient', 'Insectivore', 'The emperor scorpion is one of the largest scorpions alive, a glossy black arachnid that digs burrows in the soils of West Africa and hunts insects after dark. Adults average about 20 cm from the mouth to the tip of the tail and use their oversized pincers to tear prey apart, while young animals rely more on the sting. Collecting for the pet trade is regulated under CITES Appendix II.', array['Adults average about 20 cm long, and a pregnant female can weigh more than 28 g.', 'Under ultraviolet light its armour glows pastel green or blue, a property it shares with other scorpions.', 'Females give birth to 10 to 12 live young after a gestation of about nine months, and the newborns ride on her back.', 'Despite its size it is timid and docile, and usually flees rather than fights when cornered.']::text[], '/models/emperor-scorpion.glb', null, null, 0.2, 0.03, 0.2, 0.05, '5-8 years', false, false, array['#4a4f57', '#241d18']::text[], '🦂', 'insect', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000106', 'deathstalker-scorpion', 'Deathstalker Scorpion', 'Leiurus quinquestriatus', 'Arachnid', 'Desert, scrub & dry wadis of North Africa and the Middle East', 'Africa', 'Data Deficient', 'Insectivore', 'The deathstalker is a pale yellow scorpion of the deserts and dry scrub between North Africa and western India, and one of the most venomous scorpions known. It shelters by day under stones and in scraped burrows, emerging at night to take insects and other scorpions with slender pincers. Its sting is intensely painful and can be dangerous to children, the elderly and anyone with a heart condition.', array['Its venom is a cocktail of neurotoxins, including chlorotoxin and charybdotoxin, with a very low lethal dose for mammals.', 'Field measurements put adults at 80 to 110 mm long and 1 to 2.5 g in weight.', 'Healthy adults usually survive a sting, but the pain can last for days and envenomation always carries a risk of severe allergic reaction.', 'It is also called the Palestine yellow scorpion, and other members of its genus are widely sold as pets.']::text[], '/models/deathstalker-scorpion.glb', null, null, 0.08, 0.002, 0.08, 0.03, 'Unknown', false, false, array['#d8c07a', '#3a3122']::text[], '🦂', 'insect', 74),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000107', 'goliath-birdeater', 'Goliath Birdeater', 'Theraphosa blondi', 'Arachnid', 'Upland rainforest burrows of northern South America', 'South America', 'Data Deficient', 'Insectivore', 'The goliath birdeater is the heaviest spider known, a tarantula of the northern South American rainforest that waits at the mouth of a silk-lined burrow for insects, frogs and the occasional small rodent. Its name is misleading: the first specimen collected was found with a hummingbird, but birds are not a routine part of its diet. Females mature slowly and live far longer than males, which die within months of reaching adulthood.', array['It can weigh up to 175 g with a body 13 cm long and a leg span approaching 30 cm, second in span only to the giant huntsman spider.', 'Its venom is weak for a spider; its real defences are barbed urticating hairs it flicks at attackers.', 'Females mature in three to six years and live 15 to 25 years, while males live only three to six years.', 'Threatened, it stridulates by rubbing bristles on its pedipalps and legs together, producing an audible hiss.']::text[], '/models/goliath-birdeater.glb', null, null, 0.3, 0.175, 0.3, 0.05, '15-25 years', false, false, array['#6b4a2f', '#241a12']::text[], '🕷️', 'insect', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000110', 'luna-moth', 'Luna Moth', 'Actias luna', 'Insect', 'Deciduous hardwood forest of eastern North America', 'North America', 'Data Deficient', 'Herbivore', 'The luna moth is a pale lime-green giant silk moth of eastern North America, with long twisted tails trailing from its hindwings. Adults emerge in late spring without mouthparts, mate and lay eggs on walnut, hickory and other host trees, then die within about a week. Northern populations produce a single generation a year, while southern ones may run to two or three.', array['A typical wingspan is 11.4 cm, and large individuals exceed 17 cm.', 'The adults cannot feed at all, so they live about a week on the reserves built up as caterpillars.', 'Its spinning tails are thought to scramble the echolocation of hunting bats.', 'In the north the pupa overwinters and a single generation takes a full year.']::text[], '/models/luna-moth.glb', null, null, 0.114, 0.0005, 0.114, 0.03, 'About 1 year, 7-10 days as an adult', false, false, array['#a9d178', '#28361f']::text[], '🦋', 'insect', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000114', 'european-mantis', 'European Mantis', 'Mantis religiosa', 'Insect', 'Grassland, scrub & gardens across Europe and Asia', 'Europe', 'Least Concern', 'Insectivore', 'The European mantis is a large praying mantis of grassland, scrub and gardens, and the only member of its order native to much of central Europe. It waits motionless with folded raptorial forelegs and strikes at flies, grasshoppers and other insects in a fraction of a second, holding prey while it feeds. Females are the heavier sex and glue their eggs into a hardened foam case, the ootheca, on stems and stones.', array['Adults are 6 to 8 cm long, with males noticeably slighter than females.', 'Each compound eye holds 8,000 to 10,000 ommatidia and detects movement almost instantly.', 'It sees moving prey easily but is nearly blind to still objects, so it hunts with a stop-and-go approach.', 'Threatened, it rears up, spreads its wings and reveals coloured markings on its forelegs in a deimatic display.']::text[], '/models/european-mantis.glb', null, null, 0.07, 0, 0.07, 0.02, 'Unknown', false, false, array['#6fa43a', '#33261a']::text[], '🦗', 'insect', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000115', 'emperor-dragonfly', 'Emperor Dragonfly', 'Anax imperator', 'Insect', 'Large ponds, lakes & slow rivers across Africa and Eurasia', 'Europe', 'Least Concern', 'Insectivore', 'The emperor dragonfly is the largest dragonfly in most of Europe, a powerful hawker with a blue or green abdomen marked by a dark central line. Males patrol territories along the water''s edge and chase off rivals, while females flick eggs alone into floating pondweed. The larvae are aquatic ambush predators and the bulkiest of the European hawkers before they climb a stem to emerge as winged adults.', array['Adults are about 78 mm long with an average wingspan of 104 mm.', 'It is the largest dragonfly in most of Europe, and is still expanding northwards as the climate warms.', 'Its larvae grow to 45 to 56 mm, the largest of the European hawkers.', 'Hunting on the wing, it takes butterflies, other dragonflies and even tadpoles.']::text[], '/models/emperor-dragonfly.glb', null, null, 0.078, 0, 0.078, 0.01, 'Unknown', false, false, array['#2f6fb0', '#1d3a4a']::text[], '🪰', 'insect', 68),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000116', 'blue-ringed-octopus', 'Blue-ringed Octopus', 'Hapalochlaena lunulata', 'Cephalopod', 'Shallow coral and rock reefs of the Indo-Pacific', 'Oceans', 'Least Concern', 'Carnivore', 'The greater blue-ringed octopus is a small, golf-ball-sized cephalopod of Indo-Pacific reefs, patterned with iridescent blue rings it flashes when threatened. It hunts crabs and shrimps by pouncing, wrapping them in its arms and biting through the shell to inject venom that paralyses the muscles used for movement. It is one of the most toxic marine animals known, and it can squeeze through any gap wider than its eye.', array['Adults do not exceed 10 cm including the arms and average about 80 g.', 'Its blue rings are 7 to 8 mm across, larger than those of any other blue-ringed octopus.', 'The rings are a warning display, pulsed on and off rather than held permanently bright.', 'Its average lifespan is about 2 years, and it matures quickly, mating the following autumn.']::text[], '/models/blue-ringed-octopus.glb', null, null, 0.1, 0.08, 0.1, 0.04, 'About 2 years', false, false, array['#e0b93c', '#1c3a5c']::text[], '🐙', 'marine', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000117', 'giant-squid', 'Giant Squid', 'Architeuthis dux', 'Cephalopod', 'Deep ocean slopes and open water, mostly 300-1000 m down', 'Oceans', 'Least Concern', 'Carnivore', 'The giant squid is the second-largest mollusc alive, a deep-ocean predator known for centuries from carcasses and from the beaks found in sperm whale stomachs. Its mantle is about 2 m long and its two feeding tentacles, usually kept retracted, can extend a further 10 m and carry toothed suckers that grip prey. Live footage in its own habitat was not captured until 2012, and genetic work suggests that all the world''s giant squid belong to a single species.', array['Its total length can exceed 10 m, most of it the two elastic feeding tentacles.', 'Sperm whales hunt it, and their stomachs often contain the squid''s indigestible beaks.', 'In July 2012 an NHK and Discovery crew filmed a live giant squid in its natural habitat for the first time.', 'Reports of 13 m animals are widely repeated, but no specimen of that size has ever been scientifically documented.']::text[], '/models/giant-squid.glb', null, null, 10, 200, 10, 0, 'Unknown', false, false, array['#b4574f', '#2a1a1e']::text[], '🦑', 'marine', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000119', 'giant-clam', 'Giant Clam', 'Tridacna gigas', 'Cephalopod', 'Coral reef sand flats of the Indo-Pacific', 'Oceans', 'Critically Endangered', 'Filter Feeder', 'Tridacna gigas is the largest bivalve alive, a reef clam that can weigh more than 200 kg and measure 1.2 m across. Adults settle in one spot for life and farm symbiotic algae in their fleshy mantle, which supplies most of their energy, so a passing shadow is enough to make the shell clamp shut. Wild populations have collapsed through overharvesting for meat and for the aquarium trade.', array['The heaviest recorded specimen measured 115 cm and was estimated at 340 kg alive.', 'It grows slowly and can live more than 100 years in the wild.', 'Most of its food comes from algae living in its tissues, which it farms in sunlight.', 'Its mantle carries hundreds of light-sensitive spots that detect shadows and trigger the shell to close.']::text[], '/models/giant-clam.glb', null, null, 1.2, 200, 1.2, 0, 'More than 100 years', false, false, array['#4f7fa8', '#2b3a2c']::text[], '🦪', 'marine', 74),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000120', 'dodo', 'Dodo', 'Raphus cucullatus', 'Bird', 'Woodland & coastal forest of Mauritius', 'Africa', 'Extinct', 'Herbivore', 'The dodo was a large, flightless pigeon that lived only on Mauritius and was gone within a century of the first ships reaching the island. It nested on the ground and had no fear of the sailors or of the rats, pigs and monkeys that came with them, so its eggs and chicks were taken faster than they could be replaced. The last accepted record is from 1662, and the species now survives mainly as bones and a dessicated head kept in Oxford.', array['It stood about 63 to 75 cm tall and probably weighed 10.6 to 17.5 kg in the wild.', 'Its closest relative was the Rodrigues solitaire, another flightless bird that sailors also drove extinct.', 'Introduced rats, pigs and monkeys raided its ground nests, and chicks were the most vulnerable stage.', 'Its extinction was not widely accepted as a recent event until the 19th century, when naturalists confirmed the bird had been real.']::text[], '/models/dodo.glb', null, null, 0.7, 13, 0.7, 0.7, 'Unknown', false, true, array['#8a8f96', '#3b3630']::text[], '🦤', 'bird', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000123', 'quagga', 'Quagga', 'Equus quagga quagga', 'Mammal', 'Karoo grassland & shrubland of South Africa', 'Africa', 'Extinct', 'Herbivore', 'The quagga was a zebra of the South African Karoo whose stripes faded out behind the shoulders, leaving a plain brown rear that made it look half horse. It grazed in herds of thirty or more and was hunted for its hide and to clear pasture, and the last captive animal died in Amsterdam on 12 August 1883. Mitochondrial DNA later showed it was not a separate species at all but the southern subspecies of the plains zebra.', array['It stood about 125 to 135 cm at the shoulder and was roughly 257 cm long.', 'In 1984 the quagga became the first extinct animal whose DNA was analysed.', 'Its stripes varied between individuals and covered only the head, neck and front of the body.', 'The Quagga Project in South Africa breeds plains zebras with quagga-like striping to bring the pattern back.']::text[], '/models/quagga.glb', null, null, 2.57, 250, 2.57, 1.3, 'Unknown', false, true, array['#a08a6a', '#3b3128']::text[], '🦓', 'quadruped', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000124', 'stellers-sea-cow', 'Steller''s Sea Cow', 'Hydrodamalis gigas', 'Mammal', 'Cold kelp beds around the Commander Islands, Bering Sea', 'Asia', 'Extinct', 'Herbivore', 'Steller''s sea cow was a giant sirenian of the cold Bering Sea, found by the naturalist Georg Steller in 1741 and hunted out of existence by 1768. It grazed kelp in shallow water, grew far larger than any dugong or manatee alive today, and had no true teeth, grinding its food between keratinous plates. Slow, buoyant and apparently unafraid of people, it was slaughtered for meat and hides within a few decades of being described.', array['It reached roughly 7.5 to 8 m in length and an estimated 8 to 10 tonnes, making it one of the largest mammals of the Holocene.', 'It had no proper teeth, grinding kelp between ridged keratinous plates set in its gums.', 'Steller recorded a heart weighing about 16 kg and a stomach 6 feet long.', 'It was extinct by 1768, only 27 years after Steller''s ship was wrecked on Bering Island.']::text[], '/models/stellers-sea-cow.glb', null, null, 8, 9000, 8, 0, 'Unknown', false, true, array['#6b6f6a', '#2c3130']::text[], '🦭', 'marine', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000125', 'meerkat', 'Meerkat', 'Suricata suricatta', 'Mammal', 'Semi-arid scrub and savanna of the Kalahari and Namib', 'Africa', 'Least Concern', 'Insectivore', 'The meerkat is a small mongoose of southern Africa''s dry scrub, living in groups of up to thirty in burrow systems it digs itself. One animal at a time stands sentinel on a mound or a bush while the others dig and forage, and the group raises its pups cooperatively: every adult feeds the young, and a female who has never bred may still suckle them.', array['A sentinel stands on its hind legs and gives a different call for a snake, a raptor and a jackal, and the group answers each differently.', 'Meerkats are largely immune to the venom of the scorpions they dig up, though a sting still hurts.', 'The dark patches around their eyes cut glare, which is why they can look straight into the desert sky for predators.', 'Pups are taught to handle live prey in stages, and adults bring them disabled scorpions to practise on.']::text[], null, null, null, 0.3, 0.73, 0.3, 0.3, '12-14 years in captivity, about 7 in the wild', false, false, array['#e3c9a2', '#4a3a26']::text[], '🦡', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000126', 'african-penguin', 'African Penguin', 'Spheniscus demersus', 'Bird', 'Cold, nutrient-rich coastal water and islands off southern Africa', 'Africa', 'Critically Endangered', 'Piscivore', 'The African penguin is the only penguin that breeds on the African continent, digging burrows in guano and sand on islands and a few mainland beaches from Namibia to Algoa Bay. It hunts sardine, anchovy and squid in cold upwellings, swimming at up to 20 km/h and diving past 100 m, and it comes ashore at dusk in tight groups to run the gauntlet of seals and gulls. The IUCN moved it from Endangered to Critically Endangered in the October 2025 Red List update, after a decline of roughly 95% since the early 20th century.', array['Its donkey-like bray gave the species its older name, the jackass penguin.', 'The pink patch above each eye is a bare gland, not feathers: it dumps heat when the bird is too warm.', 'Each bird has its own pattern of black spots on a white chest, and researchers use the pattern the way others use a fingerprint.', 'Chicks leave the colony at two to four months old and go to sea alone.']::text[], null, null, null, 0.7, 3, 0.7, 0.7, '10-27 years in the wild', false, false, array['#efece3', '#16161c']::text[], '🐧', 'bird', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000127', 'andean-condor', 'Andean Condor', 'Vultur gryphus', 'Bird', 'High Andes, Patagonian steppe and Pacific coast cliffs', 'South America', 'Vulnerable', 'Carnivore', 'The Andean condor is the largest bird of prey in the world by combined weight and wingspan: adults run about 1.3 m from bill to tail and carry a 3.3 m span on the winds that sweep the Andes. It is a scavenger, riding mountain updraughts for hours to find dead cattle, llamas and seals, and a 2020 study logged birds covering more than 170 km in a day without a single flap. It nests on inaccessible rock ledges and raises one chick at a time, which stays with its parents for over a year.', array['It is the only large vulture in which the sexes look clearly different: males have a comb on the head and bigger neck wattles.', 'A 2020 study found Andean condors flap their wings for about 1% of the time they are airborne.', 'It is a national symbol in Bolivia, Chile, Colombia and Ecuador and appears on their coats of arms.', 'One captive bird is recorded as living past 70 years, which makes the species one of the longest-lived birds known.']::text[], null, null, null, 1.3, 11, 1.3, 0, 'Over 50 years; some individuals past 70', false, false, array['#e6e2d8', '#22232a']::text[], '🦅', 'bird', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000128', 'atlantic-puffin', 'Atlantic Puffin', 'Fratercula arctica', 'Bird', 'North Atlantic coasts and islands, from Maine to Norway', 'Europe', 'Vulnerable', 'Piscivore', 'The Atlantic puffin is a small auk that spends most of the year alone on the open Atlantic and crowds onto cliff-top burrows in spring to breed. Its parrot-bright bill is a seasonal ornament whose outer plates are shed after the chicks fledge, and it is a pursuit diver that catches sand eels one after another while holding the ones it has already caught. On land it waddles; in the air it beats its wings up to 400 times a minute and can reach 88 km/h.', array['Its colourful bill plates drop off after breeding, leaving a smaller, duller beak for the winter at sea.', 'The tongue and inward-pointing spines in the bill let it hold a row of sand eels while catching the next one; one bird was recorded carrying 62.', 'A chick, called a puffling, leaves its burrow at night and flies straight out to sea alone, not returning to land for years.', 'Puffins do not breed until they are four or five years old, and they use the same burrow year after year.']::text[], null, null, null, 0.3, 0.5, 0.3, 0.3, 'About 20 years in the wild', false, false, array['#e79b3c', '#1e1f26']::text[], '🐦', 'bird', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000129', 'atlas-moth', 'Atlas Moth', 'Attacus atlas', 'Insect', 'Lowland rainforest, scrub and orchards from India to Indonesia', 'Asia', 'Data Deficient', 'Herbivore', 'The Atlas moth is one of the largest insects that flies, with a wing area of about 160 cm² and a wingspan usually between 25 and 30 cm. The adult has no working mouthparts, so it lives a week or two on fat stored as a caterpillar, flying at night to find a mate and lay eggs while the caterpillars feed up on citrus, cinnamon and other leaves. The tips of its wings are shaped and marked like snake heads, and a bird that strikes at the tip misses the body.', array['Its cocoon is spun from brown silk worked commercially in India as fagara silk.', 'The caterpillar is pale green dusted with white wax and reaches 11 cm before it pupates.', 'A female releases a pheromone that males can follow from over a kilometre away.', 'The wings carry no blue or green pigment at all; the colour comes from the structure of the scales.']::text[], null, null, null, 0.3, 0, 0.3, 0.05, 'About two weeks as an adult, and it cannot feed in that time', false, false, array['#a4552f', '#241a14']::text[], '🦋', 'insect', 64),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000130', 'bactrian-camel', 'Bactrian Camel', 'Camelus bactrianus', 'Mammal', 'Cold desert, steppe and mountain pasture of Central Asia', 'Asia', 'Data Deficient', 'Herbivore', 'The Bactrian camel is the two-humped camel of Central Asia, domesticated about 4,500 years ago and still kept for transport, wool and milk from Iran to Mongolia. Its humps hold fat rather than water and shrink as the animal draws on them, and a thirsty camel can drink more than 100 litres in one session and put back a third of its body mass. The domestic animal is not assessed on the IUCN Red List; the wild Bactrian camel, Camelus ferus, is listed as Critically Endangered with fewer than 1,000 animals left in the Gobi.', array['Two rows of eyelashes, hairy ear canals and nostrils that close completely keep sandstorms out.', 'It can lose up to a third of its body mass in winter and rehydrate without harm, which most mammals cannot survive.', 'The feet spread into a broad two-toed pad so the animal does not sink into sand, unlike the narrower foot of the one-humped camel.', 'Its wild relative Camelus ferus survives in only a few areas of Mongolia and China.']::text[], null, null, null, 3, 600, 3, 2, 'About 40-50 years', false, false, array['#b6874f', '#33261b']::text[], '🐫', 'quadruped', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000131', 'bengal-tiger', 'Bengal Tiger', 'Panthera tigris tigris', 'Mammal', 'Tropical forest, mangrove and grassland of the Indian subcontinent', 'Asia', 'Endangered', 'Carnivore', 'The Bengal tiger is the most numerous tiger subspecies, found in India, Nepal, Bhutan and Bangladesh, and one of the largest cats alive: adult males average around 220 kg and run over 3 m from nose to tail tip. It hunts alone at night, stalking close before pulling down deer, wild boar and gaur, and it needs large blocks of forest with water and cover. India''s 2022 census counted 3,682 wild tigers, roughly three-quarters of the world total.', array['Every tiger''s stripe pattern is unique, and the skin under the fur is striped too.', 'White tigers are Bengal tigers carrying a recessive colour mutation, not a separate species or albinos.', 'A tiger can eat up to 40 kg of meat in a night and then go several days without feeding.', 'Its roar carries about 3 km, and it can also produce a low, infrasonic call that people feel more than hear.']::text[], null, null, null, 3.1, 220, 3.1, 1.1, '8-10 years in the wild, up to 26 in captivity', false, false, array['#d9832b', '#241610']::text[], '🐅', 'quadruped', 96),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000132', 'bullet-ant', 'Bullet Ant', 'Paraponera clavata', 'Insect', 'Lowland rainforest floor and canopy from Nicaragua to the Amazon', 'South America', 'Data Deficient', 'Omnivore', 'The bullet ant is a large rainforest ant, 18-30 mm long with a reddish-black body, that forages alone in the leaf litter and in the canopy for nectar, plant sap and small arthropods. Its sting holds the top score on the Schmidt pain index, 4.0 out of 4, and delivers a peptide venom, poneratoxin, that blocks the sodium channels nerve and muscle cells use to fire, leaving the limb shaking and the pain lasting a full day. Colonies of several hundred live at the base of a tree, and the ants hiss by rubbing a scraper over a file on the waist when disturbed.', array['Entomologist Justin Schmidt rated its sting the worst of any insect: ''like walking over flaming charcoal with a 3-inch nail in your heel''.', 'Poneratoxin paralyses by jamming the sodium channels that carry nerve impulses, and no antivenom exists.', 'Brazil''s Sateré-Mawé people use the ants in initiation gloves, and a boy must wear them for several minutes at a time, repeatedly.', 'Its stridulation — a hiss made by rubbing two body parts together — acts as a warning before it stings.']::text[], null, null, null, 0.03, 0, 0.03, 0.01, 'Unknown', false, false, array['#8c3a1d', '#1c110d']::text[], '🐜', 'insect', 66),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000133', 'caracal', 'Caracal', 'Caracal caracal', 'Mammal', 'Dry scrub, savanna, and woodland edge across Africa and into Asia', 'Africa', 'Least Concern', 'Carnivore', 'The caracal is a slender, long-legged cat of dry country, standing about 45 cm at the shoulder and carrying black ear tufts that give it the Afrikaans name rooikat and the Persian siyah-gosh, black ear. It hunts at dusk and at night, taking rodents, hares, hyraxes and small antelope, and it can leap two to three metres from a standing start to take a bird out of the air. It is solitary and territorial, and its numbers are holding across most of a range that runs from South Africa to India.', array['It can jump almost 3 m straight up and, in a single leap, swat two birds out of the air with one paw.', 'Until the 20th century caracals were tamed and used to course game in India and Iran, much as cheetahs were.', 'Its ear tufts are not part of hearing: they appear to help it aim a strike at the back of a bird''s neck.', 'Captive caracals have reached about 20 years, roughly twice the lifespan of a wild one.']::text[], null, null, null, 0.9, 12, 0.9, 0.45, 'About 12 years in the wild; captive animals up to 20', false, false, array['#c98a54', '#2b1d16']::text[], '🐈', 'quadruped', 74),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000134', 'chinese-giant-salamander', 'Chinese Giant Salamander', 'Andrias davidianus', 'Amphibian', 'Cold, rocky hill streams and lakes of central and southern China', 'Asia', 'Critically Endangered', 'Carnivore', 'The Chinese giant salamander is the largest amphibian alive: an average adult measures about 1.3 m and weighs 25-30 kg, and the largest animals recorded reached 1.8 m. It lives entirely in cold, clear streams, hiding by day in rock crevices and sucking in fish, crabs, frogs and smaller salamanders at night, and it takes most of its oxygen through skin that hangs in loose folds along the flanks. Hunted by the tonne for food and then farmed in the millions, wild populations have fallen by more than 80%, and genetic work since 2018 has shown that what was called one species is at least three.', array['It has tiny, lidless eyes and hunts by smell and by sensing movement in the water rather than by sight.', 'Chinese country people call it wawayu, baby fish, because its cry is said to sound like a child.', 'Adults have no gills at all; the folds of skin along the body are the surface through which they breathe.', 'Farms have released or lost so many animals that the genetics of the remaining wild populations are now mixed.']::text[], null, null, null, 1.3, 25, 1.3, 0, 'Unknown', false, false, array['#6f5c46', '#221a14']::text[], '🦎', 'quadruped', 72),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000135', 'common-octopus', 'Common Octopus', 'Octopus vulgaris', 'Cephalopod', 'Shallow rocky reefs, seagrass and sand of the Atlantic and Mediterranean', 'Oceans', 'Least Concern', 'Carnivore', 'The common octopus is a shallow-water hunter with a body the size of a fist and arms that stretch about a metre tip to tip. It leaves its den at dusk to take crabs, clams and small fish, drilling shells and prising them apart with a beak it can hide deep in the arm crown, and it can change colour and skin texture in under a second by pulling pigment sacs open with fine muscles. It lives fast: one or two years, breeding once, and the female starves while guarding her eggs and dies after they hatch.', array['Around two-thirds of its roughly 500 million neurons sit in its arms rather than its brain.', 'It has three hearts: two pump blood through the gills and the third drives it around the body.', 'Its blood is blue, because the oxygen carrier is haemocyanin — a copper-based molecule that works poorly in cold, low-oxygen water.', 'It can squeeze through any opening wider than its beak, which is the only rigid part of the animal.']::text[], null, null, null, 1, 3, 1, 0, '1-2 years', false, false, array['#c96b4a', '#2a1b2e']::text[], '🐙', 'marine', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000136', 'common-seahorse', 'Common Seahorse', 'Hippocampus kuda', 'Fish', 'Seagrass, mangroves and estuaries of the Indo-Pacific', 'Oceans', 'Vulnerable', 'Carnivore', 'Hippocampus kuda, the common or yellow seahorse, is a fish of Indo-Pacific estuaries, seagrass beds and mangroves that swims upright with a fin on its back and steers with a second pair of tiny fins behind the eyes. It has no stomach, so food passes through within hours and it must take small shrimps almost continuously, sucking them in through a toothless snout. Its tail is prehensile and has no fin, which lets it hold onto a blade of seagrass through a tidal current.', array['The male carries the pregnancy: the female transfers eggs into his brood pouch and he gives birth to as many as a thousand young.', 'Seahorses have no stomach, so they feed almost constantly and can take thousands of tiny crustaceans in a day.', 'The eyes move independently, one watching for prey while the other watches for predators.', 'Dried for traditional medicine and sold for aquariums, it is one of the most heavily traded seahorses in the world.']::text[], null, null, null, 0.25, 0, 0.25, 0, 'Unknown; laboratory and aquarium records suggest 1-5 years', false, false, array['#d9a53c', '#2a2317']::text[], '🐠', 'marine', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000137', 'emperor-penguin', 'Emperor Penguin', 'Aptenodytes forsteri', 'Bird', 'Fast ice and polynyas around the Antarctic continent', 'Antarctica', 'Endangered', 'Piscivore', 'The emperor penguin is the tallest and heaviest penguin, about 1.1 m and 22-45 kg, and the only bird that breeds in the Antarctic winter. The female lays a single egg on the sea ice in May or June and returns to the ocean; the male balances it on his feet under a fold of skin for about 65 days without eating, losing up to 45% of his body weight while the colony huddles through temperatures below -40 °C. The IUCN moved the species from Near Threatened to Endangered on 9 April 2026, on projections that the population will halve by the 2080s as fast ice breaks up earlier.', array['It dives deeper than any other bird: one recorded dive reached 564 m and lasted over 20 minutes.', 'In a huddle of thousands, birds shuffle constantly so that each takes a turn at the freezing edge rather than staying in the warm middle.', 'A breeding male can go about 115 days without food from arriving at the colony to being relieved by the female.', 'Its heart rate drops sharply during a long dive, slowing how fast it burns the oxygen stored in its blood and muscle.']::text[], null, null, null, 1.1, 30, 1, 1.1, 'Typically 20 years in the wild; some individuals reach 50', false, false, array['#f0c04a', '#15151e']::text[], '🐧', 'bird', 93),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000138', 'galapagos-tortoise', 'Galápagos Tortoise', 'Chelonoidis niger', 'Reptile', 'Volcanic highlands, dry lowlands and lava fields of the Galápagos Islands', 'South America', 'Vulnerable', 'Herbivore', 'The Galápagos tortoise is the largest tortoise alive, with males of the biggest populations reaching about 1.5 m and over 250 kg, and it is divided into 15 subspecies on different islands, of which 12 survive. Shell shape follows the habitat: domed on the cool, wet highlands where grass is plentiful, and saddle-backed on dry islands, where the raised front lets the neck stretch up to browse cactus. The animals move between the lowlands and the highlands with the seasons, and sleep up to 16 hours a day; the surviving subspecies are individually Red-Listed, from Vulnerable to Critically Endangered, and the complex as a whole is published as Vulnerable.', array['A tortoise can go a year without food or water, storing water in its bladder and drawing on it slowly.', 'Lonesome George, the last Pinta Island tortoise, died in 2012 and his subspecies is Extinct.', 'Captive Galápagos tortoises have lived past 175 years, and a wild lifespan of over 100 is routine.', 'The vice-governor of the islands told Darwin he could name an animal''s island from its shell — a remark that fed into his thinking on evolution.']::text[], null, null, null, 1.5, 250, 1.5, 0.6, 'Over 100 years in the wild, up to 177 in captivity', false, false, array['#5e5340', '#1f1a12']::text[], '🐢', 'quadruped', 87),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000139', 'golden-toad', 'Golden Toad', 'Incilius periglenes', 'Amphibian', 'Elfin cloud forest above Monteverde, Costa Rica, 1,500-1,620 m', 'North America', 'Extinct', 'Insectivore', 'The golden toad lived in a few square kilometres of elfin cloud forest above Monteverde in Costa Rica and nowhere else on Earth. Males were a brilliant, almost luminous orange and gathered at temporary pools for a few days each April to breed; females were olive with red spots, and for the rest of the year the toads stayed in damp burrows among the roots. Hundreds were counted in 1987, one male was found in 1988 and none has been seen since; the species was assessed as Extinct in 2004, with a severe El Niño year, upslope warming and the amphibian chytrid fungus all implicated.', array['It was known from an area of about 8 km² on the Cordillera de Tilarán — one of the smallest ranges of any vertebrate.', 'Males and females look so different in colour that early visitors assumed two species were breeding together.', 'It became the standard example of amphibian decline: the forest around it looked intact while the toads disappeared.', 'It survives only as preserved specimens, photographs and the field notes of the herpetologists who watched it go.']::text[], null, null, null, 0.05, 0, 0.05, 0.02, 'Unknown', false, true, array['#f2a93b', '#2b1d10']::text[], '🐸', 'quadruped', 70),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000140', 'gooty-tarantula', 'Gooty Tarantula', 'Poecilotheria metallica', 'Arachnid', 'Dry deciduous forest patches of Andhra Pradesh, southern India', 'Asia', 'Critically Endangered', 'Insectivore', 'The Gooty tarantula, or Gooty sapphire ornamental, is an arboreal spider known from a few fragments of dry deciduous forest in Andhra Pradesh, and it is the only tarantula with a metallic blue body. Adults have a leg span of 15-20 cm and live in tree holes and under loose bark, rushing out at night to take insects, lizards and small frogs. It was described in 1899 from a railway junction town, was not seen alive again for over a century, and is listed as Critically Endangered because the little forest it needs is fragmented and cut for firewood.', array['The blue is structural — light bent by microscopic layers in the hairs — not a pigment, and it fades to grey-brown after death.', 'Females live 11-12 years, rarely 15; males die within about a year of reaching maturity.', 'A living specimen was not found again in the wild until 2001, more than a hundred years after the first was collected.', 'Its bite is one of the few tarantula bites considered medically significant: the venom causes cramps and muscle pain that can last for days.']::text[], null, null, null, 0.2, 0, 0.2, 0.04, 'Females 11-12 years, males about 3', false, false, array['#4a6fbe', '#131a2c']::text[], '🕷️', 'insect', 68),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000141', 'green-anaconda', 'Green Anaconda', 'Eunectes murinus', 'Reptile', 'Flooded forest, swamps and slow rivers of the Amazon and Orinoco basins', 'South America', 'Least Concern', 'Carnivore', 'The green anaconda is the heaviest snake in the world, a river and swamp dweller of the Amazon and Orinoco basins in which females grow far larger than males — a mature female averages about 4.6 m against roughly 3 m for a male. It hunts in shallow, flooded forest, lying in wait and then seizing capybara, caiman, peccary and fish and coiling until the prey stops breathing, and it can stay submerged for ten minutes with only the eyes and nostrils above the surface. In 2024 genetic work argued that the northern populations are a separate species, the northern green anaconda.', array['The heaviest reliably weighed individual was a 5.21 m female of about 97 kg.', 'It gives birth to live young: litters run from 20 to 40, and one litter of 82 was recorded.', 'The 10 m anacondas of travellers'' tales have never survived measurement; the longest verified animals are a little over 6 m.', 'Its eyes and nostrils sit on top of the skull, so it can watch the bank while the rest of the body stays hidden.']::text[], null, null, null, 5, 70, 5, 0, 'About 10 years in the wild, longer in captivity', false, false, array['#4f6b34', '#151e12']::text[], '🐍', 'serpent', 86),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000142', 'hyacinth-macaw', 'Hyacinth Macaw', 'Anodorhynchus hyacinthinus', 'Bird', 'Pantanal wetlands and cerrado palm groves of Brazil, Bolivia and Paraguay', 'South America', 'Vulnerable', 'Herbivore', 'The hyacinth macaw is the largest flying parrot, a metre from the top of its head to the tip of its tail, and it is unmistakable in cobalt blue with bare yellow rings around the eye and the lower bill. It lives in the Pantanal and the cerrado, feeding almost entirely on the nuts of two palm species, which it opens with a bill strong enough to crack a coconut. It nests only in cavities in trees around 60 years old, and the world population is estimated in the low thousands after the pet trade took roughly 10,000 birds from the wild in the 1980s.', array['It often eats bocaíuva nuts that have already passed through cattle, which softens the shell enough to open.', 'Its bill can generate a bite strong enough to crack a coconut, and the dropped fragments feed other animals.', 'Nest cavities are so scarce that pairs compete for them, and suitable holes appear only in old palms and trees.', 'It is the largest parrot in the world by length, though the kakapo is heavier.']::text[], null, null, null, 1, 1.45, 1, 0, '50 years or more', false, false, array['#2f5fc4', '#11172c']::text[], '🦜', 'bird', 84),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000143', 'kea', 'Kea', 'Nestor notabilis', 'Bird', 'Alpine scrub, tussock and beech forest of New Zealand''s South Island', 'Oceania', 'Endangered', 'Omnivore', 'The kea is the only alpine parrot in the world, an olive-green bird of the South Island mountains that lives above the treeline and eats roots, leaves, berries, insects, carrion and the fat of any dead animal it finds. It explores by taking things apart: keas unclip ski-lift fittings, shred windscreen wipers and rubber seals and open rubbish bins, and they have been filmed cooperating on multi-step puzzles to reach food. The IUCN lists the species as Endangered, with introduced stoats and possums, lead poisoning and human conflict among the pressures on it.', array['Keas have a distinct musky smell — unusual in a parrot — which mammals can use to find them.', 'In puzzle tests, one kea will hold a lever while another pulls a string, then swap roles.', 'The median lifespan of a wild kea that reaches adulthood is only about five years, though the oldest captive bird reached 50.', 'Its name is the Māori word for its own screech, which carries across the valleys it patrols.']::text[], null, null, null, 0.48, 0.9, 0.48, 0, 'Median about 5 years in the wild; the oldest captive kea reached 50', false, false, array['#a3b043', '#2a2416']::text[], '🦜', 'bird', 74),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000144', 'leatherback-turtle', 'Leatherback Turtle', 'Dermochelys coriacea', 'Reptile', 'Open ocean from the tropics to the North Atlantic and subantarctic water', 'Oceans', 'Vulnerable', 'Carnivore', 'The leatherback is the largest sea turtle, reaching about 2.2 m and 500 kg, and the only one without a bony shell: instead it is covered by leathery, rubbery skin studded with thousands of tiny platelets over a layer of oily, insulating tissue. It feeds almost entirely on jellyfish, diving past 1,000 m and generating enough of its own heat to hunt in cold northern water where other sea turtles cannot. Females return to tropical beaches to lay about 100 eggs at a time in four to seven clutches, and nest temperature decides the sex of the hatchlings.', array['Its front flippers can span 2.7 m from tip to tip, proportionally the largest of any sea turtle.', 'One tagged animal swam more than 20,000 km in under two years.', 'Its throat is lined with backward-pointing spines that stop slippery jellyfish from escaping.', 'Adults have no scales on the shell and no teeth at all; the beak has a pair of pointed cusps for gripping jellyfish.']::text[], null, null, null, 2.2, 500, 2.2, 0, 'Unknown; published estimates run from 30 to over 100 years', false, false, array['#c9c3b4', '#1b2026']::text[], '🐢', 'marine', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000145', 'mountain-gorilla', 'Mountain Gorilla', 'Gorilla beringei beringei', 'Mammal', 'Highland forest of the Virunga volcanoes and Bwindi, 2,200-4,300 m', 'Africa', 'Endangered', 'Herbivore', 'The mountain gorilla lives in only two highland blocks — the Virunga volcanoes and Uganda''s Bwindi forest — between about 2,200 and 4,300 m, and it is the only great ape whose numbers are rising. Adults eat leaves, shoots, pith and bark, up to 20 kg a day, and every animal builds a fresh nest of folded vegetation each night. A silverback leads a group of related females and their young, chooses where it feeds and sleeps, and defends it; the protected population passed 1,000 animals in the 2016 census.', array['Every gorilla has a unique pattern of wrinkles around its nose, and researchers use it as a fingerprint.', 'Each animal builds its own new nest of bent branches every evening, on the ground or in a tree.', 'The chest-beat is mostly a long-distance signal answering another group''s call, not the prelude to a charge that films suggest.', 'Numbers climbed from about 620 animals in 1989 to over 1,000 in the 2016 census — the only great ape increasing.']::text[], null, null, null, 1.7, 155, 1.5, 1.7, '35-40 years in the wild, up to 50 in captivity', false, false, array['#4a4a46', '#17181c']::text[], '🦍', 'quadruped', 92),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000146', 'ocean-sunfish', 'Ocean Sunfish', 'Mola mola', 'Fish', 'Temperate and tropical open ocean worldwide', 'Oceans', 'Vulnerable', 'Carnivore', 'The ocean sunfish is the heaviest bony fish alive, a disc of an animal 1.8 m long and around a tonne that looks like a fish with the back half missing: it has no true tail fin, only a rudder of fused fin rays, and it steers with two tall fins above and below the body. It feeds on jellyfish and salps, lying on its side at the surface to warm up between deep, cold dives and to let seabirds pick parasites off its skin. A female releases up to 300 million eggs, the largest clutch recorded for any vertebrate.', array['It grows from a 2.5 mm larva to over 1,000 kg — an increase of some 60 million times, the largest growth factor known in a vertebrate.', 'One tracked individual dived to 844 m and covered 26 km in a day.', 'Its food, jellyfish, is so low in energy that it must eat enormous quantities, and it grows fast on it.', 'The name comes from its habit of lying flat on the surface, apparently basking in the sun.']::text[], null, null, null, 2.5, 1000, 1.8, 2.5, 'Unknown in the wild; up to about 10 years in captivity', false, false, array['#94a1ad', '#1b2126']::text[], '🐟', 'marine', 76),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000147', 'ocellaris-clownfish', 'Ocellaris Clownfish', 'Amphiprion ocellaris', 'Fish', 'Coral reefs and lagoons of the Indo-Pacific, to about 15 m', 'Oceans', 'Least Concern', 'Omnivore', 'The ocellaris clownfish is an 11 cm reef fish, orange with three white bars outlined in black, that lives only among the stinging tentacles of a few sea anemone species. A coat of mucus hides it from the anemone''s stinging cells, and it pays for the shelter by fanning the anemone with its fins, dropping food into it and chasing off butterflyfish that would eat it. Every clownfish begins life as a male, and if the breeding female dies, the largest male in the group changes sex and takes her place.', array['All clownfish hatch male; the dominant fish becomes female, and the change cannot be reversed.', 'A female lays 100-1,000 eggs on a rock beside the anemone, and the male guards and fans them for about a week.', 'It rarely moves more than a few metres from its anemone in its entire life.', 'It can live 6-10 years, a long life for a fish of its size.']::text[], null, null, null, 0.11, 0, 0.11, 0, '6-10 years', false, false, array['#e8722a', '#20161a']::text[], '🐠', 'marine', 91),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000148', 'przewalskis-horse', 'Przewalski''s Horse', 'Equus ferus przewalskii', 'Mammal', 'Dry steppe and desert grassland of Mongolia and north-west China', 'Asia', 'Endangered', 'Herbivore', 'Przewalski''s horse is the only truly wild horse left. It has 66 chromosomes where the domestic horse has 64, a stocky build standing about 1.3 m at the shoulder, a dun coat, a dark upright mane and no forelock at all. Driven out of the steppe during the 20th century, it survived only in zoos; from a founding stock of roughly a dozen animals, reintroductions began in Mongolia in the 1990s and there are now several thousand, many of them living wild at Hustai and Takhin Tal.', array['It was extinct in the wild by the 1960s, and every living animal descends from about a dozen captive founders.', 'Domestic horses have a forelock falling over the forehead; Przewalski''s horse has none.', 'It was named for the Russian explorer Nikolai Przhevalsky, who obtained the first specimen for science around 1880.', 'It has never been successfully tamed for riding: even hand-reared animals stay difficult to handle.']::text[], null, null, null, 2.1, 300, 2.1, 1.35, 'About 20 years', false, false, array['#c9a066', '#2b2418']::text[], '🐎', 'quadruped', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000149', 'red-bellied-piranha', 'Red-bellied Piranha', 'Pygocentrus nattereri', 'Fish', 'Amazon basin rivers, oxbow lakes and flooded forest', 'South America', 'Least Concern', 'Carnivore', 'The red-bellied piranha is a 30 cm Amazon basin fish with a deep, blunt head, an orange-red belly and a row of triangular teeth that shear like scissors. It feeds mostly on other fish, insects and crustaceans and is also a scavenger and a fruit eater, and the shoals of 20 to 30 animals that alarm swimmers form mainly for defence against caimans and river dolphins. Attacks on people are rare and usually follow blood in the water or fish trapped in a shrinking pool in the dry season.', array['It replaces its teeth in halves: one side of the jaw sheds and regrows as a unit while the other keeps working.', 'Piranhas bark — a muscle vibrates the swim bladder to produce drumming sounds used in fights and as alarm calls.', 'They shoal for protection, not because a crowd can eat more: in low water a big shoal is harder for a caiman to pick off.', 'The name comes from Tupi and means tooth fish.']::text[], null, null, null, 0.3, 1, 0.3, 0, '10 years or more', false, false, array['#c8443a', '#221312']::text[], '🐟', 'marine', 82),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000150', 'red-kangaroo', 'Red Kangaroo', 'Osphranter rufus', 'Mammal', 'Arid and semi-arid inland Australia, scrub and open grassland', 'Oceania', 'Least Concern', 'Herbivore', 'The red kangaroo is the largest living marsupial: males stand about 1.5 m and weigh 55-90 kg and are rusty red across the inland, while the smaller females are blue-grey. It eats grasses and shrubs that sheep and cattle cannot use, and it survives on very little water by concentrating its urine and staying still through the heat of the day. Females control their reproduction closely: they can pause the development of an embryo until the joey in the pouch is weaned, and they produce different milk for a newborn and an older joey at the same time.', array['A red kangaroo can hop at over 50 km/h and clear 8 m in a single bound.', 'The pouch young is born after about 33 days, the size of a jellybean, and crawls to the pouch unaided.', 'It cools itself by licking its forearms: the evaporating saliva does the work, because kangaroos barely sweat.', 'Males are boomers, females are fliers and the young are joeys in Australian usage.']::text[], null, null, null, 1.6, 55, 1.6, 1.5, 'Up to 22 years in the wild', false, false, array['#c1613a', '#291a13']::text[], '🦘', 'biped', 90),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000151', 'reindeer', 'Reindeer', 'Rangifer tarandus', 'Mammal', 'Arctic tundra, taiga and mountain birch woodland of the far north', 'Europe', 'Vulnerable', 'Herbivore', 'The reindeer, called caribou in North America, is the only deer in which both sexes grow antlers and the most northerly deer there is, living on tundra and in taiga from Norway to Greenland and Canada. In winter it digs through snow with its hooves and antlers to reach lichen, and its gut microbes break down food that other large herbivores cannot use. Herds follow the growing season over enormous distances: some caribou populations migrate farther overland each year than any other mammal, and the IUCN assesses the species as Vulnerable.', array['Its eyes change colour with the season, from gold in summer to deep blue in winter, which scatters the dim polar light and helps it spot wolves and lichen.', 'Its hooves click as it walks — the sound comes from a tendon slipping over a bone — so a herd is heard before it is seen.', 'Females keep their antlers through the winter and use them to defend craters they have dug down to the lichen; bulls shed theirs in early winter.', 'Reindeer can see ultraviolet light, which makes wolf fur and urine show up against snow.']::text[], null, null, null, 2, 100, 2, 1.2, 'Females over 15 years; bulls usually fewer than 10', false, false, array['#9a7a55', '#27201a']::text[], '🦌', 'quadruped', 88),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000152', 'reticulated-python', 'Reticulated Python', 'Malayopython reticulatus', 'Reptile', 'Rainforest, plantations and canals of Southeast Asia', 'Asia', 'Least Concern', 'Carnivore', 'The reticulated python is the longest snake in the world, a Southeast Asian constrictor that commonly reaches 4-5 m and carries the complex net-like pattern that gives it its name. It hunts in rainforest, plantations and canals, swims well enough to have reached small islands, and large individuals take pigs, deer and other mammals, swallowing prey with a gape wider than their own head. Females lay 15-80 eggs and coil around them, twitching their muscles to raise the temperature, and the hatchlings fend for themselves from the first day.', array['It is the longest snake species: most adults are 3-5 m, animals over 6 m are rare but well documented, and heavy wild females pass 70 kg.', 'The incubating female generates heat by shivering, one of the few snakes known to warm its own eggs.', 'It extends its windpipe forward out of the way so that it can keep breathing while a large meal goes down.', 'In 2017 a reticulated python in Sulawesi was confirmed to have swallowed an adult man, one of a handful of such records.']::text[], null, null, null, 5, 75, 5, 0, 'Unknown', false, false, array['#a8894f', '#1d1a12']::text[], '🐍', 'serpent', 83),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000153', 'sea-otter', 'Sea Otter', 'Enhydra lutris', 'Mammal', 'Kelp beds and shallow coastal water of the North Pacific', 'North America', 'Endangered', 'Carnivore', 'The sea otter is the heaviest member of the weasel family and the only one that lives entirely in the sea, feeding in the kelp forests of the North Pacific and sleeping wrapped in a strand of kelp so it does not drift. It has no blubber, so it keeps warm with the densest fur of any mammal and by eating about a quarter of its body weight a day in clams, urchins, crabs and abalone. Its appetite for urchins protects the kelp, which is why it is treated as a keystone species; the fur trade took the species to a few hundred animals off California, and it remains Endangered.', array['It uses tools: otters crack shells with stones, and some carry a favourite stone in a fold of skin under the foreleg.', 'Its fur runs to roughly 100,000 hairs per square centimetre, about a million per square inch — the densest of any mammal.', 'Rafts of resting otters hold hands or wrap themselves in kelp so that they do not drift apart while asleep.', 'The California population has recovered from a few dozen animals to around 3,000, still a fraction of its former range.']::text[], null, null, null, 1.4, 30, 1.4, 0.25, 'Up to 23 years in the wild', false, false, array['#7a5a41', '#1d1712']::text[], '🦦', 'quadruped', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000154', 'southern-cassowary', 'Southern Cassowary', 'Casuarius casuarius', 'Bird', 'Tropical rainforest of New Guinea and north-east Queensland', 'Oceania', 'Least Concern', 'Herbivore', 'The southern cassowary is the third-tallest bird in the world, a heavy flightless bird of New Guinea and north-eastern Queensland, black-plumaged with a blue face, red neck wattles and a horn-like casque of keratin on the head. It eats fallen fruit, swallowing large drupes whole and passing the seeds intact, which makes it the only animal able to disperse the seeds of several big-fruited rainforest trees. The female lays the eggs and leaves; the male incubates them and rears the striped chicks alone for about nine months.', array['Its inner toe carries a dagger-like claw up to 12 cm long, and its kick has killed people — Guinness lists it as the world''s most dangerous bird.', 'The purpose of the casque is still argued over: sound reception, cooling and pushing through undergrowth have all been proposed.', 'It swallows fruit whole and spreads the seeds of dozens of rainforest trees, including some that nothing else can move.', 'The male does all the incubation and chick-rearing; the larger, brighter female moves on to lay in another nest.']::text[], null, null, null, 1.7, 45, 1.7, 1.6, '20-40 years in captivity; wild lifespan poorly known', false, false, array['#4f7fd6', '#16191f']::text[], '🐦', 'bird', 78),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000155', 'three-toed-sloth', 'Three-toed Sloth', 'Bradypus tridactylus', 'Mammal', 'Lowland rainforest canopy of northern South America', 'South America', 'Least Concern', 'Herbivore', 'The three-toed sloth — this entry follows the pale-throated species, one of four in the genus Bradypus — lives in the canopy of northern South American rainforest, hanging from hooked claws and moving so slowly that algae grow in the grooves of its fur and turn it green. It eats leaves, shoots and buds, which give little energy and digest slowly, so it sleeps up to 15 hours a day and comes to the ground roughly once a week to urinate and defecate, the most dangerous thing it does. Females give birth to a single young that clings to the mother''s chest for months.', array['It has eight or nine neck vertebrae instead of the seven usual in mammals, so it can turn its head almost right round without moving its body.', 'Its body temperature follows the air around it and can fall to about 30 °C, lower than any other mammal of its size.', 'Algae and moths live in its fur, and the green tint they give is camouflage in a canopy full of hawks and eagles.', 'It can barely crawl on the ground, dragging itself by its front claws, but it swims well and crosses rivers that way.']::text[], null, null, null, 0.55, 4.5, 0.55, 0.2, 'Unknown', false, false, array['#8a7a58', '#292217']::text[], '🦥', 'quadruped', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000156', 'thylacine', 'Thylacine', 'Thylacinus cynocephalus', 'Mammal', 'Dry eucalypt forest, woodland and grassland of Tasmania', 'Oceania', 'Extinct', 'Carnivore', 'The thylacine, or Tasmanian tiger, was the largest marsupial carnivore of modern times: a wolf-shaped animal about 1.3 m long with a stiff tail, a very wide gape and a row of dark bars across the hindquarters, carrying its young in a pouch that opened backwards. It was shot, trapped and poisoned under a Tasmanian government bounty from 1888 to 1909, and the last known animal died in the Hobart zoo on 7 September 1936, although the species was not formally declared extinct until 1986. It is now the subject of a de-extinction project trying to rebuild its genome from a preserved specimen.', array['It could open its jaws to about 80°, wider than any other mammal, and the gape is visible in the surviving photographs.', 'Its pouch faced backwards, which kept the young out of the scrub as the animal ran.', 'The Tasmanian government paid bounties on 2,184 animals between 1888 and 1909.', 'The species was declared extinct 50 years after the last one died — the delay is why searches for it continued into the 1980s.']::text[], null, null, null, 1.3, 20, 1.3, 0.6, 'Unknown; the longest-lived captive animal reached about 12 years', false, true, array['#b08a5c', '#231a12']::text[], '🐺', 'quadruped', 89),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000157', 'veiled-chameleon', 'Veiled Chameleon', 'Chamaeleo calyptratus', 'Reptile', 'Mountain slopes, wadis and scrub of Yemen and south-west Saudi Arabia', 'Asia', 'Least Concern', 'Insectivore', 'The veiled chameleon is a chameleon of the Arabian Peninsula and the species most often kept in captivity. Males reach about 60 cm from snout to tail tip and grow a tall casque, a helmet of bone on the head, that females barely develop; the animal''s colour shifts from leaf green to black bands and yellow blotches with temperature, mood and breeding condition. It takes insects with a tongue that shoots out further than its own body in about a seventh of a second, and it has spread in Florida, where escaped pets have established a population.', array['Chameleons change colour mainly to signal and to control heat, not to match the background.', 'Each eye is a cone covered by a single eyelid with a small opening; the two move independently until the animal locks onto prey and ranges it in stereo.', 'The tongue is fired by elastic tissue that stores energy like a catapult, striking faster than the eye can follow.', 'Females live about 5 years and males up to 8, and a female can store sperm from one mating to fertilise later clutches.']::text[], null, null, null, 0.6, 0, 0.6, 0.15, 'About 5 years for females, up to 8 for males', false, false, array['#7fbf3c', '#1c2711']::text[], '🦎', 'quadruped', 80),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000158', 'walrus', 'Walrus', 'Odobenus rosmarus', 'Mammal', 'Shallow Arctic seas over the continental shelf, hauling out on sea ice', 'Oceans', 'Vulnerable', 'Carnivore', 'The walrus is a circumpolar Arctic relative of the seals, recognised at once by the two ivory tusks — upper canine teeth that grow throughout life — and by a muzzle of 400-700 stiff whiskers used to feel for clams in the dark sediment. Bulls run about 3 m and 1,200 kg or more, haul out on sea ice in herds and use their tusks as ice picks and in dominance displays. A walrus can eat thousands of clams a day, sucking the meat out and spitting the shells, and it dives past 100 m to find them.', array['It has inflatable air sacs in its throat that work as life jackets: a walrus can sleep floating bolt upright in the water.', 'Both sexes have tusks — upper canine teeth that keep growing all their lives — and a big bull''s can pass a metre and weigh over 5 kg; they are used to haul out onto the ice.', 'The whiskers are sensitive enough to tell a clam from a stone by touch, and the animal jets water from its mouth to wash the sediment away.', 'The oldest walrus on record, a captive male called Slowpoke, reached about 49; wild walruses live 20-30 years.']::text[], null, null, null, 3.2, 1200, 3.2, 0.9, '20-30 years in the wild', false, false, array['#a97c5e', '#2a2118']::text[], '🦭', 'marine', 85),
  ('7c9e6b1a-1f2d-4a3b-8c4d-000000000159', 'west-indian-manatee', 'West Indian Manatee', 'Trichechus manatus', 'Mammal', 'Coastal shallows, rivers and springs of Florida, the Caribbean and the Gulf', 'North America', 'Vulnerable', 'Herbivore', 'The West Indian manatee is a 3.5 m, 500 kg aquatic herbivore of Florida, the Caribbean and the Gulf of Mexico with no hind limbs at all — the tail is a broad paddle that drives it slowly along. It grazes seagrass and freshwater plants for up to eight hours a day, eating perhaps a tenth of its body weight, and it replaces its teeth continuously: worn molars drop out at the front while new ones form at the back and migrate forward. It cannot turn its head sideways, so it turns its whole body to look at something.', array['Its closest living relatives are elephants, and like them it has nails on its flippers and keeps replacing its teeth throughout life.', 'It has only six neck vertebrae, which is why it must turn its entire body to look behind it.', 'It surfaces to breathe every few minutes but can rest submerged for up to about 20 minutes.', 'In winter, Florida manatees crowd into warm springs and power-station outflows; the oldest known captive animal lived to 69.']::text[], null, null, null, 3.5, 500, 3.5, 0.8, 'About 50 years in the wild; captive animals have reached 69', false, false, array['#7c8a8c', '#1c2225']::text[], '🐋', 'marine', 84)
